import { AdminDayOfWeek, AdminOperatingHour } from '../types/storeLiveOps';

export type OperatingHoursTemplateType = 'EVERY_DAY' | 'WEEKDAYS' | 'WEEKENDS' | 'ALWAYS_OPEN';

const EVERY_DAY: AdminDayOfWeek[] = [
  'MONDAY',
  'TUESDAY',
  'WEDNESDAY',
  'THURSDAY',
  'FRIDAY',
  'SATURDAY',
  'SUNDAY',
];

const WEEKDAYS: AdminDayOfWeek[] = ['MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY'];
const WEEKENDS: AdminDayOfWeek[] = ['SATURDAY', 'SUNDAY'];

export const createOperatingHoursTemplate = (
  templateType: OperatingHoursTemplateType,
  openTime: string,
  closeTime: string
): AdminOperatingHour[] => {
  if (templateType === 'ALWAYS_OPEN') {
    return [];
  }

  const days =
    templateType === 'EVERY_DAY' ? EVERY_DAY : templateType === 'WEEKDAYS' ? WEEKDAYS : WEEKENDS;

  return days.map((dayOfWeek) => ({
    dayOfWeek,
    openTime,
    closeTime,
  }));
};

export const getOperatingHoursTemplateTargetDays = (
  templateType: OperatingHoursTemplateType
): AdminDayOfWeek[] => {
  if (templateType === 'WEEKDAYS') {
    return [...WEEKDAYS];
  }
  if (templateType === 'WEEKENDS') {
    return [...WEEKENDS];
  }
  return [...EVERY_DAY];
};
