import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { DeeFranchiseMenuResponse, DeeFranchiseResponse } from '../types';
import {
  AdminDeliveryFee,
  AdminLocale,
  AdminLocaleCode,
  AdminMenuPrice,
  AdminMenuTranslation,
} from '../types/menuOperations';
import {
  AdminFranchiseDetail,
  AdminFranchiseTranslation,
} from '../types/franchiseAdmin';
import { getFranchiseMenus, getFranchises } from '../utils/franchiseMenuPriceApi';
import {
  getAdminDeliveryFees,
  getAdminLocales,
  getAdminMenuPrice,
  getAdminMenuTranslations,
  updateAdminDeliveryFee,
  updateAdminMenuPrice,
  updateAdminMenuTranslation,
} from '../utils/menuOperationsApi';
import { updateAdminFranchiseMenuAvailability } from '../utils/storeLiveOpsApi';
import ConfirmDialog from '../components/ConfirmDialog';
import {
  deleteAdminFranchiseImage,
  getAdminFranchiseDetail,
  getAdminFranchiseTranslations,
  updateAdminFranchiseTranslation,
  uploadAdminFranchiseImage,
} from '../utils/franchiseAdminApi';
import { useToast } from '../hooks/useToast';

interface TranslationDraft {
  name: string;
  description: string;
  section: string;
}

interface FranchiseTranslationDraft {
  name: string;
  description: string;
}

interface ConfirmState {
  title: string;
  description: React.ReactNode;
  confirmLabel: string;
  tone: 'danger' | 'primary';
  action: () => Promise<void>;
}

const FRANCHISE_LANG_ORDER: AdminLocaleCode[] = ['KO', 'EN', 'JA', 'ZH_CN', 'ZH_TW'];

const FRANCHISE_LANG_LABEL: Record<string, string> = {
  KO: '한국어',
  EN: 'English',
  JA: '日本語',
  ZH_CN: '简体中文',
  ZH_TW: '繁體中文',
};

const toDraft = (translation: AdminMenuTranslation | undefined): TranslationDraft => ({
  name: translation?.name ?? '',
  description: translation?.description ?? '',
  section: translation?.section ?? '',
});

const toFranchiseDraft = (
  translation: AdminFranchiseTranslation | undefined
): FranchiseTranslationDraft => ({
  name: translation?.name ?? '',
  description: translation?.description ?? '',
});

const formatPreviewAmount = (currencyCode: string, amount: number, locales: AdminLocale[]) => {
  const locale = locales.find((item) => item.currencyCode === currencyCode);
  const fractionDigits = locale?.decimalPrecision ?? 0;
  return `${currencyCode} ${amount.toLocaleString(undefined, {
    minimumFractionDigits: fractionDigits,
    maximumFractionDigits: fractionDigits,
  })}`;
};

const FranchiseManagementPage: React.FC = () => {
  const { showToast } = useToast();
  const [locales, setLocales] = useState<AdminLocale[]>([]);
  const [franchises, setFranchises] = useState<DeeFranchiseResponse[]>([]);
  const [menus, setMenus] = useState<DeeFranchiseMenuResponse[]>([]);
  const [selectedFranchiseId, setSelectedFranchiseId] = useState('');
  const [selectedMenuId, setSelectedMenuId] = useState('');
  const [translations, setTranslations] = useState<AdminMenuTranslation[]>([]);
  const [activeLanguageCode, setActiveLanguageCode] = useState<AdminLocaleCode>('KO');
  const [translationDraft, setTranslationDraft] = useState<TranslationDraft>(toDraft(undefined));
  const [menuPrice, setMenuPrice] = useState<AdminMenuPrice | null>(null);
  const [priceInput, setPriceInput] = useState('');
  const [deliveryFees, setDeliveryFees] = useState<AdminDeliveryFee[]>([]);
  const [deliveryFeeInputs, setDeliveryFeeInputs] = useState<Record<string, string>>({});
  const [bulkMenuIds, setBulkMenuIds] = useState<Set<string>>(new Set());
  const [confirmState, setConfirmState] = useState<ConfirmState | null>(null);

  const [franchiseDetail, setFranchiseDetail] = useState<AdminFranchiseDetail | null>(null);
  const [franchiseTranslations, setFranchiseTranslations] = useState<AdminFranchiseTranslation[]>([]);
  const [activeFranchiseLang, setActiveFranchiseLang] = useState<AdminLocaleCode>('KO');
  const [franchiseDraft, setFranchiseDraft] = useState<FranchiseTranslationDraft>(
    toFranchiseDraft(undefined)
  );
  const [loadingFranchiseDetail, setLoadingFranchiseDetail] = useState(false);
  const imageInputRef = useRef<HTMLInputElement>(null);

  const [loadingInitial, setLoadingInitial] = useState(true);
  const [loadingMenus, setLoadingMenus] = useState(false);
  const [loadingMenuDetail, setLoadingMenuDetail] = useState(false);
  const [submitting, setSubmitting] = useState<string | null>(null);

  const enabledLocales = useMemo(
    () => [...locales].filter((locale) => locale.enabled).sort((a, b) => a.displayOrder - b.displayOrder),
    [locales]
  );

  const translationLocales = useMemo(() => {
    const translationCodes = new Set(translations.map((translation) => translation.languageCode));
    return enabledLocales.filter((locale) => translationCodes.has(locale.code));
  }, [enabledLocales, translations]);

  const activeTranslation = useMemo(
    () => translations.find((translation) => translation.languageCode === activeLanguageCode),
    [activeLanguageCode, translations]
  );

  const activeLocale = useMemo(
    () => locales.find((locale) => locale.code === activeLanguageCode),
    [activeLanguageCode, locales]
  );

  const orderedFranchiseTranslations = useMemo(
    () =>
      [...franchiseTranslations].sort(
        (a, b) =>
          FRANCHISE_LANG_ORDER.indexOf(a.languageCode) -
          FRANCHISE_LANG_ORDER.indexOf(b.languageCode)
      ),
    [franchiseTranslations]
  );

  const koFranchiseTranslation = useMemo(
    () => franchiseTranslations.find((translation) => translation.languageCode === 'KO'),
    [franchiseTranslations]
  );

  const activeFranchiseTranslation = useMemo(
    () => franchiseTranslations.find((translation) => translation.languageCode === activeFranchiseLang),
    [activeFranchiseLang, franchiseTranslations]
  );

  useEffect(() => {
    const loadInitialData = async () => {
      setLoadingInitial(true);
      try {
        const [localeResult, franchiseResult, deliveryFeeResult] = await Promise.all([
          getAdminLocales(),
          getFranchises('ko'),
          getAdminDeliveryFees(),
        ]);
        setLocales([...localeResult].sort((a, b) => a.displayOrder - b.displayOrder));
        setFranchises([...franchiseResult].sort((a, b) => a.name.localeCompare(b.name, 'ko')));
        setDeliveryFees(deliveryFeeResult);
        setDeliveryFeeInputs(
          deliveryFeeResult.reduce<Record<string, string>>((acc, fee) => {
            acc[fee.policyKey] = String(fee.feeKrw);
            return acc;
          }, {})
        );
      } catch (error) {
        showToast(
          error instanceof Error ? error.message : '프랜차이즈 관리 초기 데이터를 불러오지 못했습니다.',
          'error'
        );
      } finally {
        setLoadingInitial(false);
      }
    };

    loadInitialData();
  }, [showToast]);

  const loadFranchiseInfo = useCallback(
    async (franchiseId: string) => {
      setLoadingFranchiseDetail(true);
      try {
        const [detailResult, translationResult] = await Promise.all([
          getAdminFranchiseDetail(franchiseId),
          getAdminFranchiseTranslations(franchiseId),
        ]);
        setFranchiseDetail(detailResult);
        setFranchiseTranslations(translationResult);
        const koTranslation = translationResult.find((item) => item.languageCode === 'KO');
        setActiveFranchiseLang('KO');
        setFranchiseDraft(toFranchiseDraft(koTranslation));
      } catch (error) {
        showToast(
          error instanceof Error ? error.message : '프랜차이즈 정보를 불러오지 못했습니다.',
          'error'
        );
      } finally {
        setLoadingFranchiseDetail(false);
      }
    },
    [showToast]
  );

  useEffect(() => {
    if (!selectedFranchiseId) {
      setMenus([]);
      setSelectedMenuId('');
      setBulkMenuIds(new Set());
      setTranslations([]);
      setMenuPrice(null);
      setFranchiseDetail(null);
      setFranchiseTranslations([]);
      setFranchiseDraft(toFranchiseDraft(undefined));
      return;
    }

    loadFranchiseInfo(selectedFranchiseId);

    const loadMenus = async () => {
      setLoadingMenus(true);
      setSelectedMenuId('');
      setBulkMenuIds(new Set());
      setTranslations([]);
      setMenuPrice(null);
      try {
        const result = await getFranchiseMenus(selectedFranchiseId, 'ko');
        setMenus([...result].sort((a, b) => a.name.localeCompare(b.name, 'ko')));
      } catch (error) {
        showToast(error instanceof Error ? error.message : '프랜차이즈 메뉴를 불러오지 못했습니다.', 'error');
      } finally {
        setLoadingMenus(false);
      }
    };

    loadMenus();
  }, [loadFranchiseInfo, selectedFranchiseId, showToast]);

  const loadMenuOperations = useCallback(
    async (franchiseId: string, menuId: string) => {
      setLoadingMenuDetail(true);
      try {
        const [translationResult, priceResult] = await Promise.all([
          getAdminMenuTranslations(franchiseId, menuId),
          getAdminMenuPrice(franchiseId, menuId),
        ]);
        setTranslations(translationResult);
        const firstLanguage = translationResult[0]?.languageCode ?? 'KO';
        setActiveLanguageCode(firstLanguage);
        setTranslationDraft(toDraft(translationResult[0]));
        setMenuPrice(priceResult);
        setPriceInput(String(priceResult.priceKrw));
      } catch (error) {
        showToast(error instanceof Error ? error.message : '메뉴 상세 정보를 불러오지 못했습니다.', 'error');
      } finally {
        setLoadingMenuDetail(false);
      }
    },
    [showToast]
  );

  useEffect(() => {
    if (!selectedFranchiseId || !selectedMenuId) {
      setTranslations([]);
      setMenuPrice(null);
      return;
    }
    loadMenuOperations(selectedFranchiseId, selectedMenuId);
  }, [loadMenuOperations, selectedFranchiseId, selectedMenuId]);

  const handleSelectLanguage = (languageCode: AdminLocaleCode) => {
    const translation = translations.find((item) => item.languageCode === languageCode);
    setActiveLanguageCode(languageCode);
    setTranslationDraft(toDraft(translation));
  };

  const handleSelectFranchiseLang = (languageCode: AdminLocaleCode) => {
    const translation = franchiseTranslations.find((item) => item.languageCode === languageCode);
    setActiveFranchiseLang(languageCode);
    setFranchiseDraft(toFranchiseDraft(translation));
  };

  const refreshFranchiseTranslations = async () => {
    if (!selectedFranchiseId) return;
    const result = await getAdminFranchiseTranslations(selectedFranchiseId);
    setFranchiseTranslations(result);
    const refreshedActive = result.find((item) => item.languageCode === activeFranchiseLang);
    setFranchiseDraft(toFranchiseDraft(refreshedActive));
  };

  const handleSaveFranchiseTranslation = async () => {
    if (!selectedFranchiseId || activeFranchiseLang === 'KO') return;
    setSubmitting('franchise-translation');
    try {
      await updateAdminFranchiseTranslation(selectedFranchiseId, activeFranchiseLang, {
        name: franchiseDraft.name,
        description: franchiseDraft.description,
      });
      await refreshFranchiseTranslations();
      showToast(
        `${FRANCHISE_LANG_LABEL[activeFranchiseLang] ?? activeFranchiseLang} 프랜차이즈 번역을 저장했습니다.`,
        'success'
      );
    } catch (error) {
      showToast(error instanceof Error ? error.message : '프랜차이즈 번역 저장에 실패했습니다.', 'error');
    } finally {
      setSubmitting(null);
    }
  };

  const handleSelectImageFile = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    event.target.value = '';
    if (!file || !selectedFranchiseId) return;
    setSubmitting('franchise-image');
    try {
      const result = await uploadAdminFranchiseImage(selectedFranchiseId, file);
      setFranchiseDetail((prev) => (prev ? { ...prev, imageUrl: result.imageUrl } : prev));
      showToast('대표 이미지를 업로드했습니다.', 'success');
    } catch (error) {
      showToast(error instanceof Error ? error.message : '대표 이미지 업로드에 실패했습니다.', 'error');
    } finally {
      setSubmitting(null);
    }
  };

  const handleDeleteImage = async () => {
    if (!selectedFranchiseId) return;
    if (!window.confirm('대표 이미지를 삭제하시겠습니까?')) return;
    setSubmitting('franchise-image');
    try {
      await deleteAdminFranchiseImage(selectedFranchiseId);
      setFranchiseDetail((prev) => (prev ? { ...prev, imageUrl: null } : prev));
      showToast('대표 이미지를 삭제했습니다.', 'success');
    } catch (error) {
      showToast(error instanceof Error ? error.message : '대표 이미지 삭제에 실패했습니다.', 'error');
    } finally {
      setSubmitting(null);
    }
  };

  const refreshTranslations = async () => {
    if (!selectedFranchiseId || !selectedMenuId) return;
    const result = await getAdminMenuTranslations(selectedFranchiseId, selectedMenuId);
    setTranslations(result);
    const refreshedActive = result.find((item) => item.languageCode === activeLanguageCode);
    setTranslationDraft(toDraft(refreshedActive));
  };

  const refreshPrice = async () => {
    if (!selectedFranchiseId || !selectedMenuId) return;
    const result = await getAdminMenuPrice(selectedFranchiseId, selectedMenuId);
    setMenuPrice(result);
    setPriceInput(String(result.priceKrw));
  };

  const handleSaveTranslation = async () => {
    if (!selectedFranchiseId || !selectedMenuId || activeLanguageCode === 'KO') return;
    setSubmitting('translation');
    try {
      await updateAdminMenuTranslation(selectedFranchiseId, selectedMenuId, activeLanguageCode, {
        name: translationDraft.name,
        description: translationDraft.description,
        section: translationDraft.section,
      });
      await refreshTranslations();
      showToast(`${activeLocale?.nativeLabel || activeLanguageCode} 번역을 저장했습니다.`, 'success');
    } catch (error) {
      showToast(error instanceof Error ? error.message : '번역 저장에 실패했습니다.', 'error');
    } finally {
      setSubmitting(null);
    }
  };

  const refreshDeliveryFees = async () => {
    const result = await getAdminDeliveryFees();
    setDeliveryFees(result);
    setDeliveryFeeInputs(
      result.reduce<Record<string, string>>((acc, fee) => {
        acc[fee.policyKey] = String(fee.feeKrw);
        return acc;
      }, {})
    );
  };

  const handleSavePrice = async () => {
    if (!selectedFranchiseId || !selectedMenuId) return;
    const priceKrw = Number(priceInput);
    if (!Number.isFinite(priceKrw) || priceKrw < 0) {
      showToast('0 이상의 KRW 가격을 입력해주세요.', 'error');
      return;
    }
    setSubmitting('price');
    try {
      await updateAdminMenuPrice(selectedFranchiseId, selectedMenuId, { priceKrw });
      await refreshPrice();
      showToast('KRW 가격을 저장했습니다.', 'success');
    } catch (error) {
      showToast(error instanceof Error ? error.message : '가격 저장에 실패했습니다.', 'error');
    } finally {
      setSubmitting(null);
    }
  };

  const handleSaveDeliveryFee = async (deliveryFee: AdminDeliveryFee) => {
    const feeKrw = Number(deliveryFeeInputs[deliveryFee.policyKey]);
    if (!Number.isFinite(feeKrw) || feeKrw < 0) {
      showToast('0 이상의 KRW 배송비를 입력해주세요.', 'error');
      return;
    }
    setSubmitting(`delivery-${deliveryFee.policyKey}`);
    try {
      await updateAdminDeliveryFee(deliveryFee.policyKey, { feeKrw });
      await refreshDeliveryFees();
      showToast(`${deliveryFee.displayName}를 저장했습니다.`, 'success');
    } catch (error) {
      showToast(error instanceof Error ? error.message : '배송비 저장에 실패했습니다.', 'error');
    } finally {
      setSubmitting(null);
    }
  };

  const allMenusSelected = menus.length > 0 && menus.every((menu) => bulkMenuIds.has(menu.id));

  const handleToggleBulkMenu = (menuId: string) => {
    setBulkMenuIds((prev) => {
      const next = new Set(prev);
      if (next.has(menuId)) {
        next.delete(menuId);
      } else {
        next.add(menuId);
      }
      return next;
    });
  };

  const handleToggleAllMenus = () => {
    setBulkMenuIds((prev) => {
      if (menus.length > 0 && menus.every((menu) => prev.has(menu.id))) {
        return new Set();
      }
      return new Set(menus.map((menu) => menu.id));
    });
  };

  const handleApplyMenuAvailability = async (available: boolean) => {
    if (!selectedFranchiseId) return;
    const franchiseMenuIds = Array.from(bulkMenuIds);
    if (franchiseMenuIds.length === 0) {
      showToast('품절 상태를 변경할 메뉴를 선택해주세요.', 'error');
      return;
    }
    setSubmitting('menu-availability');
    try {
      await updateAdminFranchiseMenuAvailability(selectedFranchiseId, {
        franchiseMenuIds,
        storeIds: null,
        available,
      });
      const actionLabel = available ? '판매 재개' : '품절 처리';
      showToast(
        `선택한 메뉴 ${franchiseMenuIds.length}개를 전체 가게에서 ${actionLabel}했습니다.`,
        'success'
      );
      setBulkMenuIds(new Set());
    } catch (error) {
      showToast(error instanceof Error ? error.message : '메뉴 품절 상태 변경에 실패했습니다.', 'error');
    } finally {
      setSubmitting(null);
    }
  };

  const handleConfirm = async () => {
    if (!confirmState) return;
    setSubmitting('confirm');
    try {
      await confirmState.action();
    } finally {
      setSubmitting(null);
      setConfirmState(null);
    }
  };

  const requestMenuAvailability = (available: boolean) => {
    const actionLabel = available ? '판매 재개' : '품절 처리';
    setConfirmState({
      title: `전체 가게 메뉴 ${actionLabel}`,
      tone: available ? 'primary' : 'danger',
      confirmLabel: `전체 ${actionLabel}`,
      description: (
        <>
          선택한 메뉴 <strong>{bulkMenuIds.size}개</strong>를 전체 가게에서 {actionLabel}합니다.
          계속할까요?
        </>
      ),
      action: () => handleApplyMenuAvailability(available),
    });
  };

  const isFranchiseKo = activeFranchiseLang === 'KO';
  const namePlaceholder =
    !isFranchiseKo && !activeFranchiseTranslation?.explicitlySet
      ? koFranchiseTranslation?.name ?? ''
      : '';
  const descriptionPlaceholder =
    !isFranchiseKo && !activeFranchiseTranslation?.explicitlySet
      ? koFranchiseTranslation?.description ?? ''
      : '';

  return (
    <div className="min-h-full bg-gray-50 p-6">
      <div className="mb-6">
        <h1 className="text-2xl font-bold text-gray-900">프랜차이즈 관리</h1>
        <p className="mt-1 text-sm text-gray-600">
          프랜차이즈 정보(다국어 이름·설명, 대표 이미지)와 메뉴 콘텐츠·가격, 배송비를 한 곳에서 관리합니다.
        </p>
      </div>

      <section className="mb-4 rounded-lg border border-gray-200 bg-white p-4 shadow-sm">
        <div className="max-w-md">
          <label htmlFor="menu-ops-franchise" className="mb-1 block text-sm font-medium text-gray-700">
            프랜차이즈
          </label>
          <select
            id="menu-ops-franchise"
            value={selectedFranchiseId}
            onChange={(event) => setSelectedFranchiseId(event.target.value)}
            disabled={loadingInitial}
            className="w-full rounded-md border border-gray-300 px-3 py-2 text-sm"
          >
            <option value="">프랜차이즈 선택</option>
            {franchises.map((franchise) => (
              <option key={franchise.id} value={franchise.id}>
                {franchise.name}
              </option>
            ))}
          </select>
        </div>
      </section>

      {selectedFranchiseId && (
        <section
          data-testid="franchise-info-panel"
          className="mb-4 rounded-lg border border-gray-200 bg-white p-4 shadow-sm"
        >
          <div className="mb-4">
            <h2 className="text-lg font-semibold text-gray-900">프랜차이즈 정보</h2>
            <p className="mt-1 text-sm text-gray-600">
              프랜차이즈의 다국어 이름·설명과 대표 이미지를 관리합니다.
            </p>
          </div>

          {loadingFranchiseDetail ? (
            <p className="text-sm text-gray-500">프랜차이즈 정보를 불러오는 중입니다.</p>
          ) : !franchiseDetail ? (
            <p className="text-sm text-gray-500">프랜차이즈 정보를 불러오지 못했습니다.</p>
          ) : (
            <div className="grid gap-4 lg:grid-cols-[260px_1fr]">
              <div>
                <div className="mb-2 flex items-center gap-2">
                  <span className="text-sm font-medium text-gray-900">{franchiseDetail.nameKo}</span>
                  <span
                    className={`rounded-full px-2 py-0.5 text-xs font-medium ${
                      franchiseDetail.open
                        ? 'bg-green-100 text-green-700'
                        : 'bg-gray-100 text-gray-500'
                    }`}
                  >
                    {franchiseDetail.open ? '영업중' : '영업종료'}
                  </span>
                </div>
                <div className="overflow-hidden rounded-md border border-gray-200 bg-gray-50">
                  {franchiseDetail.imageUrl ? (
                    <img
                      src={franchiseDetail.imageUrl}
                      alt={`${franchiseDetail.nameKo} 대표 이미지`}
                      className="h-40 w-full object-cover"
                    />
                  ) : (
                    <div className="flex h-40 w-full items-center justify-center text-sm text-gray-400">
                      등록된 대표 이미지가 없습니다.
                    </div>
                  )}
                </div>
                <div className="mt-3 flex gap-2">
                  <input
                    ref={imageInputRef}
                    type="file"
                    accept="image/*"
                    onChange={handleSelectImageFile}
                    className="hidden"
                    aria-label="대표 이미지 파일 선택"
                  />
                  <button
                    type="button"
                    onClick={() => imageInputRef.current?.click()}
                    disabled={submitting !== null}
                    className="rounded-md bg-blue-600 px-3 py-2 text-sm font-medium text-white disabled:bg-gray-300"
                  >
                    {submitting === 'franchise-image'
                      ? '처리 중…'
                      : franchiseDetail.imageUrl
                      ? '이미지 교체'
                      : '이미지 업로드'}
                  </button>
                  {franchiseDetail.imageUrl && (
                    <button
                      type="button"
                      onClick={handleDeleteImage}
                      disabled={submitting !== null}
                      className="rounded-md border border-red-300 px-3 py-2 text-sm font-medium text-red-600 disabled:opacity-50"
                    >
                      이미지 삭제
                    </button>
                  )}
                </div>
              </div>

              <div>
                <div role="tablist" aria-label="프랜차이즈 번역 언어" className="mb-4 flex flex-wrap gap-2">
                  {orderedFranchiseTranslations.map((translation) => (
                    <button
                      key={translation.languageCode}
                      type="button"
                      role="tab"
                      aria-selected={activeFranchiseLang === translation.languageCode}
                      onClick={() => handleSelectFranchiseLang(translation.languageCode)}
                      className={`rounded-md px-3 py-2 text-sm ${
                        activeFranchiseLang === translation.languageCode
                          ? 'bg-blue-600 text-white'
                          : 'border border-gray-300 text-gray-700'
                      }`}
                    >
                      {FRANCHISE_LANG_LABEL[translation.languageCode] ?? translation.languageCode}
                    </button>
                  ))}
                </div>

                <div className="space-y-3">
                  {isFranchiseKo ? (
                    <p className="rounded-md bg-gray-50 p-3 text-sm text-gray-600">
                      한국어(기준) 값은 이 화면에서 수정할 수 없습니다. 다른 언어 번역만 편집할 수 있습니다.
                    </p>
                  ) : (
                    <>
                      {!activeFranchiseTranslation?.explicitlySet &&
                        activeFranchiseTranslation?.fallbackFrom && (
                          <p className="rounded-md bg-yellow-50 p-3 text-sm text-yellow-800">
                            저장된 번역이 없어 {activeFranchiseTranslation.fallbackFrom} 값으로 폴백됩니다.
                          </p>
                        )}
                      <p className="rounded-md bg-blue-50 p-3 text-xs text-blue-800">
                        값을 비우고 저장하면 번역이 삭제되어 한국어 기준값으로 표시됩니다.
                      </p>
                    </>
                  )}
                  <div>
                    <label htmlFor="franchise-name" className="mb-1 block text-sm font-medium text-gray-700">
                      프랜차이즈명
                    </label>
                    <input
                      id="franchise-name"
                      value={franchiseDraft.name}
                      placeholder={namePlaceholder}
                      onChange={(event) =>
                        setFranchiseDraft((prev) => ({ ...prev, name: event.target.value }))
                      }
                      disabled={isFranchiseKo}
                      className="w-full rounded-md border border-gray-300 px-3 py-2 text-sm disabled:bg-gray-100"
                    />
                  </div>
                  <div>
                    <label
                      htmlFor="franchise-description"
                      className="mb-1 block text-sm font-medium text-gray-700"
                    >
                      프랜차이즈 설명
                    </label>
                    <textarea
                      id="franchise-description"
                      value={franchiseDraft.description}
                      placeholder={descriptionPlaceholder}
                      onChange={(event) =>
                        setFranchiseDraft((prev) => ({ ...prev, description: event.target.value }))
                      }
                      disabled={isFranchiseKo}
                      className="min-h-[120px] w-full rounded-md border border-gray-300 px-3 py-2 text-sm disabled:bg-gray-100"
                    />
                  </div>
                  <button
                    type="button"
                    onClick={handleSaveFranchiseTranslation}
                    disabled={isFranchiseKo || submitting !== null}
                    className="rounded-md bg-blue-600 px-4 py-2 text-sm font-medium text-white disabled:bg-gray-300"
                  >
                    {submitting === 'franchise-translation' ? '저장 중…' : '프랜차이즈 번역 저장'}
                  </button>
                </div>
              </div>
            </div>
          )}
        </section>
      )}

      {selectedFranchiseId && (
        <section
          data-testid="menu-section"
          className="mb-4 rounded-lg border border-gray-200 bg-white p-4 shadow-sm"
        >
          <div className="mb-4">
            <h2 className="text-lg font-semibold text-gray-900">메뉴 콘텐츠·가격·품절</h2>
            <p className="mt-1 text-sm text-gray-600">
              메뉴를 선택해 다국어 콘텐츠와 KRW 가격을 편집하고, 체크한 메뉴를 전체 가게 기준으로 품절·판매 재개할 수 있습니다.
            </p>
          </div>

          <div className="grid gap-4 lg:grid-cols-[320px_1fr]">
            <div className="min-w-0">
              <div className="mb-2 flex items-center justify-between text-xs text-gray-600">
                <span>
                  선택 메뉴 <span className="font-semibold text-gray-900">{bulkMenuIds.size}</span>개
                </span>
                {menus.length > 0 && (
                  <button
                    type="button"
                    onClick={handleToggleAllMenus}
                    className="text-blue-600 hover:underline"
                  >
                    {allMenusSelected ? '전체 해제' : '전체 선택'}
                  </button>
                )}
              </div>
              <div className="mb-3 flex flex-wrap gap-2">
                <button
                  type="button"
                  onClick={() => requestMenuAvailability(false)}
                  disabled={bulkMenuIds.size === 0 || submitting !== null}
                  className="rounded-md bg-red-600 px-3 py-2 text-sm font-medium text-white disabled:bg-gray-300"
                >
                  전체 가게 품절 처리
                </button>
                <button
                  type="button"
                  onClick={() => requestMenuAvailability(true)}
                  disabled={bulkMenuIds.size === 0 || submitting !== null}
                  className="rounded-md bg-green-600 px-3 py-2 text-sm font-medium text-white disabled:bg-gray-300"
                >
                  전체 가게 판매 재개
                </button>
              </div>
              <div className="overflow-hidden rounded-md border border-gray-200">
                {loadingMenus ? (
                  <div className="p-4 text-sm text-gray-500">메뉴 목록을 불러오는 중입니다.</div>
                ) : menus.length === 0 ? (
                  <div className="p-4 text-sm text-gray-500">표시할 메뉴가 없습니다.</div>
                ) : (
                  <ul className="max-h-[420px] divide-y divide-gray-100 overflow-y-auto">
                    {menus.map((menu) => {
                      const isActive = selectedMenuId === menu.id;
                      const isChecked = bulkMenuIds.has(menu.id);
                      return (
                        <li
                          key={menu.id}
                          className={`flex items-center gap-2 px-3 py-2 ${
                            isActive ? 'bg-blue-50' : isChecked ? 'bg-blue-50/40' : 'hover:bg-gray-50'
                          }`}
                        >
                          <input
                            type="checkbox"
                            checked={isChecked}
                            onChange={() => handleToggleBulkMenu(menu.id)}
                            aria-label={`${menu.name} 일괄 선택`}
                          />
                          <button
                            type="button"
                            onClick={() => setSelectedMenuId(menu.id)}
                            className={`flex-1 text-left text-sm font-medium ${
                              isActive ? 'text-blue-700' : 'text-gray-900 hover:text-blue-700'
                            }`}
                          >
                            {menu.name}
                          </button>
                        </li>
                      );
                    })}
                  </ul>
                )}
              </div>
              <p className="mt-2 text-xs text-gray-500">
                품절·판매 재개는 전체 가게 기준으로 적용됩니다. 특정 가게만 변경하려면 가게 운영 관리를 이용하세요.
              </p>
            </div>

            <div className="min-w-0">
              {!selectedMenuId ? (
                <div className="flex min-h-[200px] items-center justify-center rounded-md border border-gray-200 text-sm text-gray-500">
                  메뉴를 선택하면 다국어 콘텐츠와 가격을 편집할 수 있습니다.
                </div>
              ) : loadingMenuDetail ? (
                <div className="flex min-h-[200px] items-center justify-center rounded-md border border-gray-200 text-sm text-gray-500">
                  메뉴 정보를 불러오는 중입니다.
                </div>
              ) : (
                <div className="grid gap-4 xl:grid-cols-[1fr_320px]">
                  <section
                    data-testid="menu-content-panel"
                    className="rounded-lg border border-gray-200 bg-white p-4 shadow-sm"
                  >
            <h2 className="mb-4 text-lg font-semibold text-gray-900">메뉴 다국어 콘텐츠</h2>
            <div role="tablist" aria-label="메뉴 번역 언어" className="mb-4 flex flex-wrap gap-2">
              {translationLocales.map((locale) => (
                <button
                  key={locale.code}
                  type="button"
                  role="tab"
                  aria-selected={activeLanguageCode === locale.code}
                  onClick={() => handleSelectLanguage(locale.code)}
                  className={`rounded-md px-3 py-2 text-sm ${
                    activeLanguageCode === locale.code
                      ? 'bg-blue-600 text-white'
                      : 'border border-gray-300 text-gray-700'
                  }`}
                >
                  {locale.nativeLabel}
                </button>
              ))}
            </div>

            {activeTranslation ? (
              <div className="space-y-3">
                {activeLanguageCode === 'KO' && (
                  <p className="rounded-md bg-gray-50 p-3 text-sm text-gray-600">
                    한국어(기준) 값은 이 화면에서 수정할 수 없습니다. 다른 언어 번역만 편집할 수 있습니다.
                  </p>
                )}
                {!activeTranslation.explicitlySet && activeTranslation.fallbackFrom && (
                  <p className="rounded-md bg-yellow-50 p-3 text-sm text-yellow-800">
                    저장된 번역이 없어 {activeTranslation.fallbackFrom} 값으로 폴백됩니다.
                  </p>
                )}
                <div>
                  <label htmlFor="translation-name" className="mb-1 block text-sm font-medium text-gray-700">
                    메뉴명
                  </label>
                  <input
                    id="translation-name"
                    value={translationDraft.name}
                    onChange={(event) =>
                      setTranslationDraft((prev) => ({ ...prev, name: event.target.value }))
                    }
                    disabled={activeLanguageCode === 'KO'}
                    className="w-full rounded-md border border-gray-300 px-3 py-2 text-sm disabled:bg-gray-100"
                  />
                </div>
                <div>
                  <label
                    htmlFor="translation-description"
                    className="mb-1 block text-sm font-medium text-gray-700"
                  >
                    상세 설명
                  </label>
                  <textarea
                    id="translation-description"
                    value={translationDraft.description}
                    onChange={(event) =>
                      setTranslationDraft((prev) => ({
                        ...prev,
                        description: event.target.value,
                      }))
                    }
                    disabled={activeLanguageCode === 'KO'}
                    className="min-h-[120px] w-full rounded-md border border-gray-300 px-3 py-2 text-sm disabled:bg-gray-100"
                  />
                </div>
                <div>
                  <label htmlFor="translation-section" className="mb-1 block text-sm font-medium text-gray-700">
                    섹션
                  </label>
                  <input
                    id="translation-section"
                    value={translationDraft.section}
                    onChange={(event) =>
                      setTranslationDraft((prev) => ({ ...prev, section: event.target.value }))
                    }
                    disabled={activeLanguageCode === 'KO'}
                    className="w-full rounded-md border border-gray-300 px-3 py-2 text-sm disabled:bg-gray-100"
                  />
                </div>
                <button
                  type="button"
                  onClick={handleSaveTranslation}
                  disabled={activeLanguageCode === 'KO' || submitting !== null}
                  className="rounded-md bg-blue-600 px-4 py-2 text-sm font-medium text-white disabled:bg-gray-300"
                >
                  {submitting === 'translation' ? '저장 중…' : '번역 저장'}
                </button>
              </div>
            ) : (
              <p className="text-sm text-gray-500">표시할 번역 정보가 없습니다.</p>
            )}
          </section>

          <section
            data-testid="menu-price-panel"
            className="rounded-lg border border-gray-200 bg-white p-4 shadow-sm"
          >
            <h2 className="mb-4 text-lg font-semibold text-gray-900">KRW 가격</h2>
            {menuPrice ? (
              <div className="space-y-4">
                <div>
                  <label htmlFor="price-krw" className="mb-1 block text-sm font-medium text-gray-700">
                    KRW 가격
                  </label>
                  <input
                    id="price-krw"
                    type="number"
                    min={0}
                    value={priceInput}
                    onChange={(event) => setPriceInput(event.target.value)}
                    className="w-full rounded-md border border-gray-300 px-3 py-2 text-sm"
                  />
                </div>
                <button
                  type="button"
                  onClick={handleSavePrice}
                  disabled={submitting !== null}
                  className="rounded-md bg-blue-600 px-4 py-2 text-sm font-medium text-white disabled:bg-gray-300"
                >
                  {submitting === 'price' ? '저장 중…' : '가격 저장'}
                </button>
                <div>
                  <h3 className="mb-2 text-sm font-semibold text-gray-700">환산 미리보기</h3>
                  <div className="space-y-1 text-sm text-gray-700">
                    {Object.entries(menuPrice.convertedPreview).map(([currencyCode, amount]) => (
                      <div key={currencyCode}>{formatPreviewAmount(currencyCode, amount, locales)}</div>
                    ))}
                  </div>
                  <p className="mt-2 text-xs text-gray-500">
                    환율 기준 시각: {menuPrice.exchangeRateFetchedAt}
                  </p>
                </div>
              </div>
            ) : (
              <p className="text-sm text-gray-500">가격 정보를 불러오지 못했습니다.</p>
            )}
                  </section>
                </div>
              )}
            </div>
          </div>
        </section>
      )}

      <section
        data-testid="delivery-fee-panel"
        className="rounded-lg border border-gray-200 bg-white p-4 shadow-sm"
      >
        <div className="mb-4">
          <h2 className="text-lg font-semibold text-gray-900">배송비 관리</h2>
          <p className="mt-1 text-sm text-gray-600">
            배송비는 프랜차이즈와 무관한 KRW 기준값으로 저장됩니다.
          </p>
        </div>
        {deliveryFees.length === 0 ? (
          <p className="text-sm text-gray-500">등록된 배송비 정책이 없습니다.</p>
        ) : (
          <div className="space-y-4">
            {deliveryFees.map((deliveryFee) => (
              <div
                key={deliveryFee.policyKey}
                className="grid gap-4 rounded-md border border-gray-100 p-4 lg:grid-cols-[240px_180px_1fr_auto]"
              >
                <div>
                  <div className="font-medium text-gray-900">{deliveryFee.displayName}</div>
                  <div className="mt-1 text-xs text-gray-500">{deliveryFee.policyKey}</div>
                  {!deliveryFee.enabled && (
                    <div className="mt-1 text-xs font-medium text-gray-400">비활성 정책</div>
                  )}
                </div>
                <div>
                  <label
                    htmlFor={`delivery-fee-${deliveryFee.policyKey}`}
                    className="mb-1 block text-sm font-medium text-gray-700"
                  >
                    {deliveryFee.displayName} KRW
                  </label>
                  <input
                    id={`delivery-fee-${deliveryFee.policyKey}`}
                    type="number"
                    min={0}
                    value={deliveryFeeInputs[deliveryFee.policyKey] ?? ''}
                    onChange={(event) =>
                      setDeliveryFeeInputs((prev) => ({
                        ...prev,
                        [deliveryFee.policyKey]: event.target.value,
                      }))
                    }
                    className="w-full rounded-md border border-gray-300 px-3 py-2 text-sm"
                  />
                </div>
                <div>
                  <h3 className="mb-2 text-sm font-semibold text-gray-700">환산 미리보기</h3>
                  <div className="flex flex-wrap gap-x-4 gap-y-1 text-sm text-gray-700">
                    {Object.entries(deliveryFee.convertedPreview).map(([currencyCode, amount]) => (
                      <span key={currencyCode}>{formatPreviewAmount(currencyCode, amount, locales)}</span>
                    ))}
                  </div>
                  <p className="mt-2 text-xs text-gray-500">
                    환산 미리보기는 마진 미적용 단순 환산값입니다.
                  </p>
                </div>
                <div className="flex items-end">
                  <button
                    type="button"
                    onClick={() => handleSaveDeliveryFee(deliveryFee)}
                    disabled={submitting !== null}
                    className="rounded-md bg-blue-600 px-4 py-2 text-sm font-medium text-white disabled:bg-gray-300"
                  >
                    {submitting === `delivery-${deliveryFee.policyKey}`
                      ? '저장 중…'
                      : `${deliveryFee.displayName} 저장`}
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </section>

      <ConfirmDialog
        isOpen={confirmState !== null}
        title={confirmState?.title ?? ''}
        description={confirmState?.description}
        confirmLabel={confirmState?.confirmLabel ?? '확인'}
        tone={confirmState?.tone ?? 'primary'}
        isProcessing={submitting === 'confirm'}
        onConfirm={handleConfirm}
        onCancel={() => setConfirmState(null)}
      />
    </div>
  );
};

export default FranchiseManagementPage;
