import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { ManualCategory } from '../types';
import {
  getManualCategoryList,
  createManualCategory,
  updateManualCategory,
  deleteManualCategory,
} from '../utils/manualCategoryApi';
import { getManualList } from '../utils/manualApi';
import { useToast } from '../hooks/useToast';
import LoadingSpinner from '../components/LoadingSpinner';
import ErrorMessage from '../components/ErrorMessage';
import ManualCategoryReorderList from '../components/ManualCategoryReorderList';
import ManualCategoryEditorModal from '../components/ManualCategoryEditorModal';
import ManualCategoryDeleteConfirmModal from '../components/ManualCategoryDeleteConfirmModal';

const ManualCategoryManagementPage: React.FC = () => {
  const navigate = useNavigate();
  const [categories, setCategories] = useState<ManualCategory[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // 모달 상태
  const [editorModalOpen, setEditorModalOpen] = useState(false);
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
  const [editingCategory, setEditingCategory] = useState<ManualCategory | null>(null);
  const [deletingCategory, setDeletingCategory] = useState<ManualCategory | null>(null);
  const [deletingCategoryManualCount, setDeletingCategoryManualCount] = useState(0);
  const [isProcessing, setIsProcessing] = useState(false);

  const { showToast } = useToast();

  // 관리자 여부 (임시로 true로 설정, 실제로는 인증 정보에서 가져와야 함)
  const isAdmin = true;

  // 관리자 체크 (실제로는 인증 정보에서 확인)
  useEffect(() => {
    if (!isAdmin) {
      showToast('관리자만 접근할 수 있습니다.', 'error');
      navigate('/manuals');
    }
  }, [isAdmin, navigate, showToast]);

  // 카테고리 목록 조회
  const fetchCategories = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const response = await getManualCategoryList();
      if (response.success) {
        const sortedCategories = response.data
          .filter((cat) => cat.isActive)
          .sort((a, b) => a.sortOrder - b.sortOrder);
        setCategories(sortedCategories);
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : '카테고리 목록을 불러오는데 실패했습니다.';
      setError(errorMessage);
      showToast(errorMessage, 'error');
    } finally {
      setLoading(false);
    }
  }, [showToast]);

  // 카테고리별 메뉴얼 개수 조회
  const fetchManualCount = useCallback(async (categoryId: string): Promise<number> => {
    try {
      const response = await getManualList({ categoryId, size: 1000 });
      if (response.success) {
        return response.data.manuals.filter((m) => m.isActive).length;
      }
      return 0;
    } catch (err) {
      console.error('메뉴얼 개수 조회 실패:', err);
      return 0;
    }
  }, []);

  // 초기 로딩
  useEffect(() => {
    fetchCategories();
  }, [fetchCategories]);

  // 카테고리 생성/수정
  const handleSaveCategory = async (name: string, sortOrder?: number) => {
    try {
      setIsProcessing(true);
      if (editingCategory) {
        // 수정
        const response = await updateManualCategory(editingCategory.id, {
          name,
          sortOrder,
        });
        if (response.success) {
          showToast('카테고리가 성공적으로 수정되었습니다.', 'success');
          setEditorModalOpen(false);
          setEditingCategory(null);
          await fetchCategories();
        }
      } else {
        // 생성
        const response = await createManualCategory({
          name,
          sortOrder,
        });
        if (response.success) {
          showToast('카테고리가 성공적으로 생성되었습니다.', 'success');
          setEditorModalOpen(false);
          await fetchCategories();
        }
      }
    } catch (err) {
      showToast(
        err instanceof Error ? err.message : '카테고리 저장에 실패했습니다.',
        'error'
      );
    } finally {
      setIsProcessing(false);
    }
  };

  // 카테고리 삭제
  const handleDeleteCategory = async () => {
    if (!deletingCategory) return;

    try {
      setIsProcessing(true);
      const response = await deleteManualCategory(deletingCategory.id);
      if (response.success) {
        showToast('카테고리가 성공적으로 삭제되었습니다.', 'success');
        setDeleteModalOpen(false);
        setDeletingCategory(null);
        await fetchCategories();
      }
    } catch (err) {
      showToast(
        err instanceof Error ? err.message : '카테고리 삭제에 실패했습니다.',
        'error'
      );
    } finally {
      setIsProcessing(false);
    }
  };

  // 카테고리 생성 모달 열기
  const handleOpenCreateModal = () => {
    setEditingCategory(null);
    setEditorModalOpen(true);
  };

  // 카테고리 수정 모달 열기
  const handleOpenEditModal = (category: ManualCategory) => {
    setEditingCategory(category);
    setEditorModalOpen(true);
  };

  // 카테고리 삭제 모달 열기
  const handleOpenDeleteModal = async (category: ManualCategory) => {
    setDeletingCategory(category);
    const count = await fetchManualCount(category.id);
    setDeletingCategoryManualCount(count);
    setDeleteModalOpen(true);
  };

  // 순서 변경 후 목록 새로고침
  const handleReorder = () => {
    fetchCategories();
  };

  return (
    <div className="max-w-7xl mx-auto">
      {/* 헤더 */}
      <div className="mb-6 flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button
            onClick={() => navigate('/manuals')}
            className="text-gray-600 hover:text-gray-900 transition-colors"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
            </svg>
          </button>
          <h1 className="text-2xl font-bold text-gray-900">카테고리 관리</h1>
        </div>
        <button
          onClick={handleOpenCreateModal}
          className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
        >
          카테고리 생성
        </button>
      </div>

      {loading && <LoadingSpinner />}

      {error && (
        <ErrorMessage message={error} onRetry={fetchCategories} />
      )}

      {!loading && !error && (
        <>
          {/* 카테고리 목록 */}
          <div className="bg-white rounded-lg shadow-sm p-6">
            <h2 className="text-lg font-semibold text-gray-900 mb-4">
              카테고리 목록 ({categories.length}개)
            </h2>
            {categories.length > 0 ? (
              <ManualCategoryReorderList
                categories={categories}
                onReorder={handleReorder}
              />
            ) : (
              <div className="text-center py-8 text-gray-500">
                등록된 카테고리가 없습니다.
              </div>
            )}
          </div>

          {/* 카테고리별 액션 버튼 */}
          {categories.length > 0 && (
            <div className="mt-6 bg-white rounded-lg shadow-sm p-6">
              <h2 className="text-lg font-semibold text-gray-900 mb-4">카테고리 관리</h2>
              <div className="space-y-2">
                {categories.map((category) => (
                  <div
                    key={category.id}
                    className="flex items-center justify-between p-4 border border-gray-200 rounded-lg"
                  >
                    <div>
                      <div className="font-semibold text-gray-900">{category.name}</div>
                      <div className="text-sm text-gray-500">순서: {category.sortOrder}</div>
                    </div>
                    <div className="flex gap-2">
                      <button
                        onClick={() => handleOpenEditModal(category)}
                        className="px-3 py-1 text-sm bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors"
                      >
                        수정
                      </button>
                      <button
                        onClick={() => handleOpenDeleteModal(category)}
                        className="px-3 py-1 text-sm bg-red-600 text-white rounded hover:bg-red-700 transition-colors"
                      >
                        삭제
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </>
      )}

      {/* 카테고리 편집 모달 */}
      <ManualCategoryEditorModal
        isOpen={editorModalOpen}
        category={editingCategory}
        onConfirm={handleSaveCategory}
        onCancel={() => {
          setEditorModalOpen(false);
          setEditingCategory(null);
        }}
        isProcessing={isProcessing}
      />

      {/* 카테고리 삭제 확인 모달 */}
      <ManualCategoryDeleteConfirmModal
        isOpen={deleteModalOpen}
        categoryName={deletingCategory?.name || ''}
        manualCount={deletingCategoryManualCount}
        onConfirm={handleDeleteCategory}
        onCancel={() => {
          setDeleteModalOpen(false);
          setDeletingCategory(null);
          setDeletingCategoryManualCount(0);
        }}
        isProcessing={isProcessing}
      />
    </div>
  );
};

export default ManualCategoryManagementPage;
