  const [includePartialRefund, setIncludePartialRefund] = useState(false);
  const [normalExcludedMenuKeys, setNormalExcludedMenuKeys] = useState<string[]>([]);
  const [soldOutMenuKeys, setSoldOutMenuKeys] = useState<string[]>([]);
  const [showCopyToast, setShowCopyToast] = useState<string | null>(null);
  const [isExpanded, setIsExpanded] = useState(false);
  const [isEmailModalOpen, setIsEmailModalOpen] = useState(false);
  const { showToast } = useToast();

  // 이메일 표시 함수
