  const getMenuKey = (menuId: number, index: number) => `${menuId}-${index}`;
  const getMenuDisplayName = (item: Order['items'][number]) => orderType === 'gift'
    ? item.name
    : (item.franchiseMenuName || item.name);

  const activeNormalExcludedMenuKeys = includePartialRefund ? normalExcludedMenuKeys : [];
