  const getAmPmText = (amPm: 'AM' | 'PM', languageCode: string) => {
    switch (languageCode) {
      case 'JA':
        return amPm === 'AM' ? '午前' : '午後';
      case 'ZH_CN':
      case 'ZH_TW':
        return amPm === 'AM' ? '上午' : '下午';
      default: // EN and others
        return amPm;
    }
  };

  // 완전한 배달 시간 문자열 생성
  const getFullDeliveryTime = (languageCode: string) => {
    if (!deliveryTime.trim()) {
      return '[배달 예상 시간을 입력해주세요]';
    }
    const [hourStr, minuteStr] = deliveryTime.split(':');
    let hour = parseInt(hourStr, 10);
    const minute = parseInt(minuteStr || '0', 10);

    if (Number.isNaN(hour) || Number.isNaN(minute)) {
      return '[배달 예상 시간을 입력해주세요]';
    }

    if (deliveryAmPm === 'AM') {
      if (hour === 12) hour = 0;
    } else if (hour !== 12) {
      hour += 12;
    }

    const displayDate = new Date();
    displayDate.setHours(hour, minute + 10, 0, 0);

    const displayHour24 = displayDate.getHours();
    const displayMinute = displayDate.getMinutes();
    const displayAmPm = displayHour24 >= 12 ? 'PM' : 'AM';
    const displayHour12 = displayHour24 % 12 || 12;
    const bufferedAmPmText = getAmPmText(displayAmPm, languageCode);
    return `${displayHour12}:${displayMinute.toString().padStart(2, '0')} ${bufferedAmPmText} `;
  };

