// 예약배달 관련 API 함수
import { OrderSheetResponse, DateFilter } from '../types';
import { apiClient } from './api';

// 예약배달 주문서 정보를 가져오는 API 함수
export const getReservationOrderSheet = async (key: string, dateFilter?: DateFilter): Promise<OrderSheetResponse> => {
  const filterParam = dateFilter && dateFilter !== DateFilter.ALL 
    ? `&dateFilter=${dateFilter}` 
    : '';
  const url = `/api/orders/reservation/sheet?key=${key}${filterParam}`;
  return apiClient.get<OrderSheetResponse>(url);
}; 