// 어드민 정산 관리 유틸리티 함수
import { SettlementRequestStatus } from '../types';

// 상태 한글 라벨
const STATUS_LABELS: Record<SettlementRequestStatus, string> = {
  REQUESTED: '요청',
  APPROVED: '승인',
  REJECTED: '반려',
  PAID: '지급완료',
  CANCELLED: '취소',
};

// 상태별 배지 색상 클래스 (Tailwind CSS)
const STATUS_COLORS: Record<SettlementRequestStatus, { bg: string; text: string }> = {
  REQUESTED: { bg: 'bg-yellow-100', text: 'text-yellow-800' },
  APPROVED: { bg: 'bg-blue-100', text: 'text-blue-800' },
  REJECTED: { bg: 'bg-red-100', text: 'text-red-800' },
  PAID: { bg: 'bg-green-100', text: 'text-green-800' },
  CANCELLED: { bg: 'bg-gray-100', text: 'text-gray-800' },
};

// 상태 라벨 반환
export const getStatusLabel = (status: SettlementRequestStatus): string => {
  return STATUS_LABELS[status] || status;
};

// 상태 배지 색상 클래스 반환
export const getStatusColorClasses = (status: SettlementRequestStatus): string => {
  const colors = STATUS_COLORS[status] || STATUS_COLORS.REQUESTED;
  return `${colors.bg} ${colors.text}`;
};

// 가능한 액션 타입
export type SettlementAction = 'approve' | 'reject' | 'complete' | 'cancel';

// 현재 상태에서 가능한 액션 목록
export const getAvailableActions = (status: SettlementRequestStatus): SettlementAction[] => {
  switch (status) {
    case 'REQUESTED':
      return ['approve', 'reject'];
    case 'APPROVED':
      return ['complete'];
    case 'PAID':
      return ['cancel'];
    case 'REJECTED':
    case 'CANCELLED':
    default:
      return [];
  }
};

// 액션 한글 라벨
export const getActionLabel = (action: SettlementAction): string => {
  switch (action) {
    case 'approve':
      return '승인';
    case 'reject':
      return '반려';
    case 'complete':
      return '지급완료';
    case 'cancel':
      return '지급완료 취소';
    default:
      return action;
  }
};

// 액션 버튼 색상 클래스
export const getActionColorClasses = (action: SettlementAction): string => {
  switch (action) {
    case 'approve':
      return 'bg-blue-600 hover:bg-blue-700 text-white';
    case 'reject':
      return 'bg-red-600 hover:bg-red-700 text-white';
    case 'complete':
      return 'bg-green-600 hover:bg-green-700 text-white';
    case 'cancel':
      return 'bg-orange-600 hover:bg-orange-700 text-white';
    default:
      return 'bg-gray-600 hover:bg-gray-700 text-white';
  }
};

// 금액 포맷팅
export const formatAmount = (amount: number): string => {
  return `${amount.toLocaleString()}원`;
};

// 날짜/시간 포맷팅 (2025-11-29 14:30:00 → 2025-11-29 14:30)
export const formatDateTime = (dateTimeString: string | null): string => {
  if (!dateTimeString) return '-';
  
  // 초 부분 제거
  const parts = dateTimeString.split(':');
  if (parts.length >= 2) {
    return `${parts[0]}:${parts[1]}`;
  }
  return dateTimeString;
};

// 모든 상태 목록 (필터용)
export const ALL_STATUSES: SettlementRequestStatus[] = [
  'REQUESTED',
  'APPROVED',
  'REJECTED',
  'PAID',
  'CANCELLED',
];

