import type {
  HostApplicationQrStatus,
  HostApplicationStatus,
} from '../types/hostApplication';

export type HostApplicationListTab = 'ALL' | 'PENDING' | 'REJECTED' | 'APPROVED';

const STATUS_LABELS: Record<HostApplicationStatus, string> = {
  PENDING: '신청',
  APPROVED: '승인',
  REJECTED: '반려',
};

const QR_STATUS_LABELS: Record<HostApplicationQrStatus, string> = {
  NOT_STARTED: '제작 전',
  QR_GENERATED: 'QR 제작',
  QR_SENT: 'QR 발송',
};

export function labelHostApplicationStatus(status: HostApplicationStatus): string {
  return STATUS_LABELS[status] ?? status;
}

export function labelHostApplicationQrStatus(
  status: HostApplicationQrStatus | null | undefined
): string {
  if (status == null) return '—';
  return QR_STATUS_LABELS[status] ?? status;
}

/** 목록 QR 열: 미연결 승인 등은 —, 연결된 승인은 null을 제작 전으로 표시 */
export function labelHostApplicationQrStatusForListRow(row: {
  status: HostApplicationStatus;
  qr_status?: HostApplicationQrStatus | null;
  linked_stay_id: string | null;
  linked_stay?: { stay_id: string } | null;
}): string {
  const hasStay = Boolean(row.linked_stay_id || row.linked_stay);
  if (row.qr_status != null) {
    return labelHostApplicationQrStatus(row.qr_status);
  }
  if (row.status === 'APPROVED' && hasStay) {
    return labelHostApplicationQrStatus('NOT_STARTED');
  }
  return '—';
}

export function hostApplicationListEmptyMessage(tab: HostApplicationListTab): string {
  switch (tab) {
    case 'ALL':
      return '전체 신청에 해당하는 건이 없습니다.';
    case 'PENDING':
      return '신청 건이 없습니다.';
    case 'REJECTED':
      return '반려 건이 없습니다.';
    case 'APPROVED':
      return '활성 스테이에 연결된 승인 건이 없습니다.';
    default:
      return '내역이 없습니다.';
  }
}
