import React, { useState, useEffect } from 'react';
import { ManualVersion, Manual } from '../types';
import { getManualVersions, getManualDetail } from '../utils/manualApi';
import { useToast } from '../hooks/useToast';
import LoadingSpinner from '../components/LoadingSpinner';
import MarkdownViewer from '../components/MarkdownViewer';
import { formatDate } from '../utils/dateUtils';

interface ManualVersionHistoryModalProps {
  isOpen: boolean;
  manualId: string;
  onClose: () => void;
}

const ManualVersionHistoryModal: React.FC<ManualVersionHistoryModalProps> = ({
  isOpen,
  manualId,
  onClose,
}) => {
  const [versions, setVersions] = useState<ManualVersion[]>([]);
  const [selectedVersion, setSelectedVersion] = useState<Manual | null>(null);
  const [loading, setLoading] = useState(false);
  const [loadingDetail, setLoadingDetail] = useState(false);
  const { showToast } = useToast();

  // 버전 히스토리 조회
  useEffect(() => {
    if (!isOpen || !manualId) return;

    const fetchVersions = async () => {
      try {
        setLoading(true);
        const response = await getManualVersions(manualId);
        if (response.success) {
          // 최신순으로 정렬
          const sortedVersions = response.data.sort((a, b) => {
            const dateA = new Date(a.createdDate).getTime();
            const dateB = new Date(b.createdDate).getTime();
            return dateB - dateA;
          });
          setVersions(sortedVersions);
        }
      } catch (err) {
        showToast(
          err instanceof Error ? err.message : '버전 히스토리를 불러오는데 실패했습니다.',
          'error'
        );
      } finally {
        setLoading(false);
      }
    };

    fetchVersions();
  }, [isOpen, manualId, showToast]);

  // 버전 클릭 시 상세 조회
  const handleVersionClick = async (versionId: string) => {
    try {
      setLoadingDetail(true);
      const response = await getManualDetail(versionId);
      if (response.success) {
        setSelectedVersion(response.data);
      }
    } catch (err) {
      showToast(
        err instanceof Error ? err.message : '버전 상세를 불러오는데 실패했습니다.',
        'error'
      );
    } finally {
      setLoadingDetail(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50">
      <div className="bg-white rounded-lg shadow-xl w-full max-w-4xl max-h-[90vh] mx-4 flex flex-col">
        {/* 헤더 */}
        <div className="flex items-center justify-between p-4 border-b border-gray-200">
          <h2 className="text-xl font-bold text-gray-900">버전 히스토리</h2>
          <button
            onClick={onClose}
            className="text-gray-400 hover:text-gray-600 transition-colors"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        {/* 내용 */}
        <div className="flex-1 overflow-hidden flex">
          {/* 버전 목록 */}
          <div className="w-1/3 border-r border-gray-200 overflow-y-auto">
            {loading ? (
              <div className="p-4">
                <LoadingSpinner />
              </div>
            ) : versions.length > 0 ? (
              <div className="p-4 space-y-2">
                {versions.map((version) => (
                  <button
                    key={version.id}
                    onClick={() => handleVersionClick(version.id)}
                    className={`w-full text-left p-3 rounded-lg border transition-colors ${
                      selectedVersion?.id === version.id
                        ? 'border-blue-500 bg-blue-50'
                        : 'border-gray-200 hover:border-gray-300 hover:bg-gray-50'
                    }`}
                  >
                    <div className="font-semibold text-gray-900">{version.title}</div>
                    <div className="text-sm text-gray-500 mt-1">
                      v{version.version} · {formatDate(version.createdDate)}
                    </div>
                  </button>
                ))}
              </div>
            ) : (
              <div className="p-4 text-center text-gray-500">
                버전 히스토리가 없습니다.
              </div>
            )}
          </div>

          {/* 선택된 버전 상세 */}
          <div className="flex-1 overflow-y-auto p-6">
            {loadingDetail ? (
              <div className="flex items-center justify-center h-full">
                <LoadingSpinner />
              </div>
            ) : selectedVersion ? (
              <div>
                <div className="mb-4">
                  <h3 className="text-lg font-semibold text-gray-900 mb-2">
                    {selectedVersion.title} (v{selectedVersion.version})
                  </h3>
                  <div className="text-sm text-gray-500">
                    작성일: {formatDate(selectedVersion.createdDate)}
                  </div>
                </div>
                <div className="prose max-w-none">
                  <MarkdownViewer content={selectedVersion.content} />
                </div>
              </div>
            ) : (
              <div className="flex items-center justify-center h-full text-gray-500">
                버전을 선택하세요.
              </div>
            )}
          </div>
        </div>

        {/* 하단 버튼 */}
        <div className="flex justify-end p-4 border-t border-gray-200">
          <button
            onClick={onClose}
            className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 transition-colors"
          >
            닫기
          </button>
        </div>
      </div>
    </div>
  );
};

export default ManualVersionHistoryModal;
