import React, { useMemo, useState } from 'react';
import {
  ActivePromotionDetail,
  Promotion,
  PromotionStaySearchItem,
  PromotionTargetStay,
} from '../types/promotion';
import {
  addPromotionTargetStay,
  createPromotion,
  createPromotionPolicy,
  getActivePromotionDetails,
  removePromotionTargetStay,
  searchStaysByName,
} from '../utils/promotionApi';
import { useToast } from '../hooks/useToast';

const toLocalDateTime = (value: string): string => {
  if (!value) {
    return value;
  }
  return value.length === 16 ? `${value}:00` : value;
};

const AdminPromotionPage: React.FC = () => {
  const { showToast } = useToast();

  // PromotionCreateRequest 전용 입력
  const [promotionName, setPromotionName] = useState('');
  const [promotionDescription, setPromotionDescription] = useState('');
  const [promotionStartDate, setPromotionStartDate] = useState('');
  const [promotionEndDate, setPromotionEndDate] = useState('');
  const [promotionIsActive, setPromotionIsActive] = useState(true);

  // 정책 추가 폼 입력
  const [policyType, setPolicyType] = useState<'DELIVERY_FEE' | 'ORDER_AMOUNT'>('DELIVERY_FEE');
  const [targetCountry, setTargetCountry] = useState('ko');
  const [discountType, setDiscountType] = useState<'FIXED_AMOUNT' | 'PERCENTAGE'>('PERCENTAGE');
  const [discountValue, setDiscountValue] = useState('');
  const [minOrderAmount, setMinOrderAmount] = useState('');
  const [maxDiscountAmount, setMaxDiscountAmount] = useState('');

  const [createdPromotion, setCreatedPromotion] = useState<Promotion | null>(null);
  const [lastPolicyId, setLastPolicyId] = useState<string | null>(null);
  const [activePromotions, setActivePromotions] = useState<ActivePromotionDetail[]>([]);
  const [isLoadingActivePromotions, setIsLoadingActivePromotions] = useState(false);
  const [selectedExistingPromotionId, setSelectedExistingPromotionId] = useState('');
  const [isUsingExistingPromotion, setIsUsingExistingPromotion] = useState(false);

  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<PromotionStaySearchItem[]>([]);
  const [selectedStay, setSelectedStay] = useState<PromotionStaySearchItem | null>(null);
  const [mappedStays, setMappedStays] = useState<PromotionTargetStay[]>([]);

  const [isCreatingPromotion, setIsCreatingPromotion] = useState(false);
  const [isAddingPolicy, setIsAddingPolicy] = useState(false);
  const [isSearching, setIsSearching] = useState(false);
  const [isMappingStay, setIsMappingStay] = useState(false);
  const [unmappingStayId, setUnmappingStayId] = useState<string | null>(null);

  const promotionId = createdPromotion?.id ?? null;
  const hasPolicy = Boolean(lastPolicyId);
  const hasMappedStay = mappedStays.length > 0;
  const currentStep = !promotionId ? 1 : !hasPolicy ? 2 : 3;
  const isSearchDisabled = searchQuery.trim().length < 2;

  const promotionFormError = useMemo(() => {
    if (!promotionName.trim()) {
      return 'name은 필수입니다.';
    }
    if (!promotionStartDate) {
      return 'startDate는 필수입니다.';
    }
    if (!promotionEndDate) {
      return 'endDate는 필수입니다.';
    }

    const startTime = new Date(promotionStartDate).getTime();
    const endTime = new Date(promotionEndDate).getTime();
    if (!Number.isNaN(startTime) && !Number.isNaN(endTime) && endTime <= startTime) {
      return 'endDate는 startDate 이후여야 합니다.';
    }

    return null;
  }, [promotionName, promotionStartDate, promotionEndDate]);

  const promotionPayloadPreview = useMemo(
    () => ({
      name: promotionName.trim(),
      ...(promotionDescription.trim() ? { description: promotionDescription.trim() } : {}),
      startDate: toLocalDateTime(promotionStartDate),
      endDate: toLocalDateTime(promotionEndDate),
      isActive: promotionIsActive,
    }),
    [promotionName, promotionDescription, promotionStartDate, promotionEndDate, promotionIsActive]
  );

  const policyFormError = useMemo(() => {
    if (!policyType) {
      return 'policyType은 필수입니다.';
    }
    if (!targetCountry.trim()) {
      return 'targetCountry는 필수입니다.';
    }
    if (!discountType) {
      return 'discountType은 필수입니다.';
    }
    if (!discountValue.trim()) {
      return 'discountValue는 필수입니다.';
    }
    const parsedDiscountValue = Number(discountValue);
    if (Number.isNaN(parsedDiscountValue) || parsedDiscountValue < 0) {
      return 'discountValue는 0 이상의 숫자여야 합니다.';
    }
    if (minOrderAmount.trim()) {
      const parsedMinOrderAmount = Number(minOrderAmount);
      if (Number.isNaN(parsedMinOrderAmount) || parsedMinOrderAmount < 0) {
        return 'minOrderAmount는 0 이상의 숫자여야 합니다.';
      }
    }
    if (maxDiscountAmount.trim()) {
      const parsedMaxDiscountAmount = Number(maxDiscountAmount);
      if (Number.isNaN(parsedMaxDiscountAmount) || parsedMaxDiscountAmount < 0) {
        return 'maxDiscountAmount는 0 이상의 숫자여야 합니다.';
      }
    }
    return null;
  }, [policyType, targetCountry, discountType, discountValue, minOrderAmount, maxDiscountAmount]);

  const policyPayloadPreview = useMemo(
    () => ({
      policyType,
      targetCountry,
      discountType,
      discountValue: Number(discountValue),
      ...(minOrderAmount.trim() ? { minOrderAmount: Number(minOrderAmount) } : {}),
      ...(maxDiscountAmount.trim() ? { maxDiscountAmount: Number(maxDiscountAmount) } : {}),
    }),
    [policyType, targetCountry, discountType, discountValue, minOrderAmount, maxDiscountAmount]
  );

  const discountValueGuide = useMemo(() => {
    const parsed = Number(discountValue);
    if (Number.isNaN(parsed) || parsed < 0) {
      return null;
    }
    if (discountType === 'PERCENTAGE') {
      return `PERCENTAGE 기준: ${parsed} = ${parsed * 100}%`;
    }
    return `FIXED_AMOUNT 기준: ${parsed} (${targetCountry.toUpperCase()} 통화 기준 고정 할인 금액)`;
  }, [discountValue, discountType, targetCountry]);

  const handleCreatePromotion = async () => {
    if (promotionFormError) {
      showToast(promotionFormError, 'error');
      return;
    }

    try {
      setIsCreatingPromotion(true);
      const response = await createPromotion(promotionPayloadPreview);

      if (!response.success) {
        throw new Error(response.message || '프로모션 생성에 실패했습니다.');
      }

      setCreatedPromotion(response.data);
      setIsUsingExistingPromotion(false);
      setLastPolicyId(null);
      setMappedStays([]);
      setSearchResults([]);
      setSelectedStay(null);
      showToast('프로모션이 생성되었습니다.', 'success');
    } catch (error) {
      showToast(
        error instanceof Error ? error.message : '프로모션 생성에 실패했습니다.',
        'error'
      );
    } finally {
      setIsCreatingPromotion(false);
    }
  };

  const handleLoadActivePromotions = async () => {
    try {
      setIsLoadingActivePromotions(true);
      const details = await getActivePromotionDetails();
      setActivePromotions(details);
      if (details.length === 0) {
        showToast('조회된 활성 프로모션이 없습니다.', 'error');
      } else {
        showToast(`활성 프로모션 ${details.length}건을 불러왔습니다.`, 'success');
      }
    } catch (error) {
      showToast(
        error instanceof Error ? error.message : '활성 프로모션 조회에 실패했습니다.',
        'error'
      );
    } finally {
      setIsLoadingActivePromotions(false);
    }
  };

  const handleSelectExistingPromotion = () => {
    if (!selectedExistingPromotionId) {
      showToast('선택할 프로모션을 먼저 고르세요.', 'error');
      return;
    }

    const selected = activePromotions.find(
      (item) => item.promotion.id === selectedExistingPromotionId
    );
    if (!selected) {
      showToast('선택한 프로모션 정보를 찾을 수 없습니다.', 'error');
      return;
    }

    setCreatedPromotion(selected.promotion);
    setIsUsingExistingPromotion(true);
    setMappedStays(selected.targetStays || []);

    const policies = (selected.promotion as any).policies;
    if (Array.isArray(policies) && policies.length > 0) {
      const lastPolicy = policies[policies.length - 1];
      setLastPolicyId(typeof lastPolicy?.id === 'string' ? lastPolicy.id : 'EXISTING_POLICY');
    } else {
      setLastPolicyId(null);
    }

    showToast('기존 프로모션이 선택되었습니다. 바로 Stay 매핑을 진행할 수 있습니다.', 'success');
  };

  const handleSwitchToCreateMode = () => {
    setIsUsingExistingPromotion(false);
    setSelectedExistingPromotionId('');
    showToast('새 프로모션 생성 모드로 전환했습니다.', 'success');
  };

  const handleAddPolicy = async () => {
    if (!promotionId) {
      showToast('먼저 프로모션을 생성해주세요.', 'error');
      return;
    }
    if (policyFormError) {
      showToast(policyFormError, 'error');
      return;
    }

    try {
      setIsAddingPolicy(true);
      const response = await createPromotionPolicy(promotionId, policyPayloadPreview);

      if (!response.success) {
        throw new Error(response.message || '정책 추가에 실패했습니다.');
      }

      setLastPolicyId(response.data.id);
      showToast('프로모션 정책이 추가되었습니다.', 'success');
    } catch (error) {
      showToast(
        error instanceof Error ? error.message : '프로모션 정책 추가에 실패했습니다.',
        'error'
      );
    } finally {
      setIsAddingPolicy(false);
    }
  };

  const handleSearchStay = async () => {
    const trimmed = searchQuery.trim();
    if (trimmed.length < 2) {
      showToast('Stay 검색어는 2자 이상 입력해주세요.', 'error');
      return;
    }

    try {
      setIsSearching(true);
      const result = await searchStaysByName(trimmed);
      setSearchResults(result);
      setSelectedStay(null);

      if (result.length === 0) {
        showToast('검색 결과가 없습니다.', 'error');
      }
    } catch (error) {
      showToast(
        error instanceof Error ? error.message : 'Stay 검색에 실패했습니다.',
        'error'
      );
    } finally {
      setIsSearching(false);
    }
  };

  const handleSearchKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && !isSearchDisabled && !isSearching) {
      handleSearchStay();
    }
  };

  const handleMapSelectedStay = async () => {
    if (!promotionId) {
      showToast('먼저 프로모션을 생성해주세요.', 'error');
      return;
    }
    if (!selectedStay) {
      showToast('매핑할 Stay를 선택해주세요.', 'error');
      return;
    }

    try {
      setIsMappingStay(true);
      const mapped = await addPromotionTargetStay(promotionId, { stayId: selectedStay.stay_id });

      const alreadyExists = mappedStays.some((item) => item.stayId === mapped.stayId);
      if (alreadyExists) {
        showToast('이미 등록된 Stay입니다.', 'success');
      } else {
        setMappedStays((prev) => [mapped, ...prev]);
        showToast('대상 Stay가 등록되었습니다.', 'success');
      }
    } catch (error) {
      showToast(
        error instanceof Error ? error.message : '대상 Stay 등록에 실패했습니다.',
        'error'
      );
    } finally {
      setIsMappingStay(false);
    }
  };

  const handleUnmapStay = async (stayId: string) => {
    if (!promotionId) {
      showToast('먼저 프로모션을 선택하거나 생성해주세요.', 'error');
      return;
    }

    setUnmappingStayId(stayId);
    try {
      await removePromotionTargetStay(promotionId, stayId);
      setMappedStays((prev) => prev.filter((item) => item.stayId !== stayId));
      showToast('대상 Stay 매핑이 해제되었습니다.', 'success');
    } catch (error) {
      showToast(
        error instanceof Error ? error.message : '대상 Stay 매핑 해제에 실패했습니다.',
        'error'
      );
    } finally {
      setUnmappingStayId(null);
    }
  };

  const stepItems = [
    { id: 1, title: '프로모션 생성', done: Boolean(promotionId) },
    { id: 2, title: '정책 추가', done: hasPolicy },
    { id: 3, title: 'Stay 매핑', done: hasMappedStay },
  ];

  return (
    <div className="max-w-5xl mx-auto px-4 py-6 space-y-6">
      <div className="space-y-2">
        <h1 className="text-2xl font-bold text-gray-900">프로모션 관리</h1>
        <p className="text-sm text-gray-600">
          순서대로 진행하면 됩니다. 현재 단계: <span className="font-semibold">Step {currentStep}</span>
        </p>
      </div>

      <section className="bg-white rounded-lg border border-gray-200 p-4">
        <ol className="grid gap-3 sm:grid-cols-3">
          {stepItems.map((step) => (
            <li
              key={step.id}
              className={`rounded-lg border px-3 py-2 ${
                step.done
                  ? 'border-green-200 bg-green-50'
                  : step.id === currentStep
                  ? 'border-blue-200 bg-blue-50'
                  : 'border-gray-200 bg-gray-50'
              }`}
            >
              <p className="text-xs text-gray-500">STEP {step.id}</p>
              <p className="text-sm font-semibold text-gray-900">{step.title}</p>
              <p className="text-xs mt-1 text-gray-600">
                {step.done ? '완료됨' : step.id === currentStep ? '진행 중' : '대기'}
              </p>
            </li>
          ))}
        </ol>
      </section>

      <section className="bg-white rounded-lg border border-gray-200 p-4 space-y-3">
        <h2 className="text-lg font-semibold text-gray-900">기존 활성 프로모션 선택</h2>
        <p className="text-sm text-gray-500">
          새로 만들지 않고, 기존 활성 프로모션을 선택해 바로 Stay에 적용할 수 있습니다.
        </p>
        <div className="flex flex-wrap gap-2">
          <button
            onClick={handleLoadActivePromotions}
            disabled={isLoadingActivePromotions}
            className="px-4 py-2 bg-gray-700 text-white rounded-lg hover:bg-gray-800 transition-colors disabled:opacity-50"
          >
            {isLoadingActivePromotions ? '조회 중...' : '활성 프로모션 조회'}
          </button>
          <button
            onClick={handleSelectExistingPromotion}
            disabled={!selectedExistingPromotionId}
            className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors disabled:opacity-50"
          >
            선택한 프로모션 적용
          </button>
          {isUsingExistingPromotion ? (
            <button
              onClick={handleSwitchToCreateMode}
              className="px-4 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-colors"
            >
              새 프로모션 생성 모드
            </button>
          ) : null}
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            활성 프로모션 목록
          </label>
          <select
            value={selectedExistingPromotionId}
            onChange={(e) => setSelectedExistingPromotionId(e.target.value)}
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          >
            <option value="">프로모션을 선택하세요</option>
            {activePromotions.map((item) => (
              <option key={item.promotion.id} value={item.promotion.id}>
                {(item.promotion as any).name || item.promotion.id} ({item.promotion.id})
              </option>
            ))}
          </select>
        </div>
        {isUsingExistingPromotion ? (
          <p className="text-sm text-indigo-600">
            기존 프로모션 적용 모드입니다. 아래 생성/정책 섹션은 숨겨지고 Stay 매핑만 진행됩니다.
          </p>
        ) : null}
      </section>

      {!isUsingExistingPromotion ? (
      <section className="bg-white rounded-lg border border-gray-200 p-4 space-y-3">
        <h2 className="text-lg font-semibold text-gray-900">1) 프로모션 생성</h2>
        <p className="text-sm text-gray-500">
          서버 DTO 형식(PromotionCreateRequest)에 맞춰 camelCase 키로 전송됩니다.
        </p>
        <div className="grid gap-3 md:grid-cols-2">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              name <span className="text-red-500">*</span>
            </label>
            <input
              value={promotionName}
              onChange={(e) => setPromotionName(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              placeholder="예: 5월 스테이 프로모션"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">description (선택)</label>
            <input
              value={promotionDescription}
              onChange={(e) => setPromotionDescription(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              placeholder="예: 테스트용"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              startDate <span className="text-red-500">*</span>
            </label>
            <input
              type="datetime-local"
              value={promotionStartDate}
              onChange={(e) => setPromotionStartDate(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              endDate <span className="text-red-500">*</span>
            </label>
            <input
              type="datetime-local"
              value={promotionEndDate}
              onChange={(e) => setPromotionEndDate(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            />
          </div>
        </div>
        <label className="inline-flex items-center gap-2 text-sm text-gray-700">
          <input
            type="checkbox"
            checked={promotionIsActive}
            onChange={(e) => setPromotionIsActive(e.target.checked)}
            className="rounded border-gray-300"
          />
          isActive (선택, 기본 true)
        </label>

        {promotionFormError ? (
          <p className="text-sm text-red-600">{promotionFormError}</p>
        ) : (
          <p className="text-xs text-gray-500">요청 payload 미리보기</p>
        )}
        <pre className="bg-gray-50 border border-gray-200 rounded-lg p-3 text-xs text-gray-700 overflow-x-auto">
          {JSON.stringify(promotionPayloadPreview, null, 2)}
        </pre>

        <div className="flex items-center justify-between">
          <div className="text-sm text-gray-600">
            {promotionId ? `생성된 promotionId: ${promotionId}` : '아직 생성된 프로모션이 없습니다.'}
          </div>
          <button
            onClick={handleCreatePromotion}
            disabled={isCreatingPromotion || Boolean(promotionFormError)}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors disabled:opacity-50"
          >
            {isCreatingPromotion ? '생성 중...' : '프로모션 생성'}
          </button>
        </div>
      </section>
      ) : null}

      {!isUsingExistingPromotion ? (
      <section className="bg-white rounded-lg border border-gray-200 p-4 space-y-3">
        <h2 className="text-lg font-semibold text-gray-900">2) 프로모션 정책 추가 (언어별)</h2>
        <p className="text-sm text-gray-500">
          생성된 promotionId에 연결할 정책을 DTO 스펙에 맞춰 입력하세요.
        </p>
        {!promotionId ? (
          <p className="text-sm text-amber-600">Step 1에서 프로모션을 먼저 생성해 주세요.</p>
        ) : (
          <>
            <div className="grid gap-3 md:grid-cols-2">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  policyType <span className="text-red-500">*</span>
                </label>
                <select
                  value={policyType}
                  onChange={(e) => setPolicyType(e.target.value as 'DELIVERY_FEE' | 'ORDER_AMOUNT')}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                >
                  <option value="DELIVERY_FEE">DELIVERY_FEE</option>
                  <option value="ORDER_AMOUNT">ORDER_AMOUNT</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  targetCountry <span className="text-red-500">*</span>
                </label>
                <select
                  value={targetCountry}
                  onChange={(e) => setTargetCountry(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                >
                  <option value="ko">ko</option>
                  <option value="en">en</option>
                  <option value="ja">ja</option>
                  <option value="zh-CN">zh-CN</option>
                  <option value="zh-TW">zh-TW</option>
                </select>
              </div>
            </div>
            <div className="grid gap-3 md:grid-cols-2">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  discountType <span className="text-red-500">*</span>
                </label>
                <select
                  value={discountType}
                  onChange={(e) => setDiscountType(e.target.value as 'FIXED_AMOUNT' | 'PERCENTAGE')}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                >
                  <option value="PERCENTAGE">PERCENTAGE</option>
                  <option value="FIXED_AMOUNT">FIXED_AMOUNT</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  discountValue <span className="text-red-500">*</span>
                </label>
                <input
                  type="number"
                  step="0.01"
                  min="0"
                  value={discountValue}
                  onChange={(e) => setDiscountValue(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  placeholder="예: 10"
                />
                <p className="mt-1 text-xs text-gray-500">
                  {discountType === 'PERCENTAGE'
                    ? 'PERCENTAGE는 1 = 100%, 0.5 = 50%, 0.1 = 10% 입니다.'
                    : 'FIXED_AMOUNT는 고정 할인 금액입니다.'}
                </p>
                {discountValueGuide ? (
                  <p className="mt-1 text-xs text-indigo-600">{discountValueGuide}</p>
                ) : null}
              </div>
            </div>
            <div className="grid gap-3 md:grid-cols-2">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  minOrderAmount (선택)
                </label>
                <input
                  type="number"
                  step="0.01"
                  min="0"
                  value={minOrderAmount}
                  onChange={(e) => setMinOrderAmount(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  placeholder="예: 10000"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  maxDiscountAmount (선택)
                </label>
                <input
                  type="number"
                  step="0.01"
                  min="0"
                  value={maxDiscountAmount}
                  onChange={(e) => setMaxDiscountAmount(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  placeholder="예: 5000"
                />
              </div>
            </div>
            {policyFormError ? (
              <p className="text-sm text-red-600">{policyFormError}</p>
            ) : (
              <p className="text-xs text-gray-500">정책 요청 payload 미리보기</p>
            )}
            <pre className="bg-gray-50 border border-gray-200 rounded-lg p-3 text-xs text-gray-700 overflow-x-auto">
              {JSON.stringify(policyPayloadPreview, null, 2)}
            </pre>
          </>
        )}

        <div className="flex items-center justify-between">
          <div className="text-sm text-gray-600">
            {lastPolicyId ? `마지막 정책 ID: ${lastPolicyId}` : '아직 추가된 정책이 없습니다.'}
          </div>
          <button
            onClick={handleAddPolicy}
            disabled={!promotionId || isAddingPolicy || Boolean(policyFormError)}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors disabled:opacity-50"
          >
            {isAddingPolicy ? '추가 중...' : '정책 추가'}
          </button>
        </div>
      </section>
      ) : null}

      <section className="bg-white rounded-lg border border-gray-200 p-4 space-y-3">
        <h2 className="text-lg font-semibold text-gray-900">3) 대상 Stay 검색/매핑</h2>
        <p className="text-sm text-gray-500">
          Stay 이름으로 검색 후 선택한 항목의 `stay_id`를 대상으로 매핑합니다.
        </p>
        {!promotionId ? (
          <p className="text-sm text-amber-600">Step 1 완료 후 검색/매핑을 진행할 수 있습니다.</p>
        ) : null}

        <div className="flex gap-2">
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            onKeyDown={handleSearchKeyDown}
            disabled={!promotionId}
            className="flex-1 px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent disabled:bg-gray-100 disabled:cursor-not-allowed"
            placeholder="Stay 이름 검색 (2자 이상)"
          />
          <button
            onClick={handleSearchStay}
            disabled={!promotionId || isSearchDisabled || isSearching}
            className="px-4 py-2 bg-gray-700 text-white rounded-lg hover:bg-gray-800 transition-colors disabled:opacity-50"
          >
            {isSearching ? '검색 중...' : '검색'}
          </button>
        </div>
        <p className="text-xs text-gray-500">검색어를 2자 이상 입력하면 Enter 키로도 검색할 수 있습니다.</p>

        <div className="border border-gray-200 rounded-lg overflow-hidden">
          {searchResults.length === 0 ? (
            <div className="p-3 text-sm text-gray-500">검색 결과가 없습니다.</div>
          ) : (
            <ul className="divide-y divide-gray-200 max-h-56 overflow-y-auto">
              {searchResults.map((item) => {
                const isSelected = selectedStay?.stay_id === item.stay_id;
                return (
                  <li key={item.id}>
                    <button
                      onClick={() => setSelectedStay(item)}
                      className={`w-full text-left px-3 py-2 hover:bg-gray-50 transition-colors ${
                        isSelected ? 'bg-blue-50' : 'bg-white'
                      }`}
                    >
                      <p className="text-sm font-medium text-gray-900">{item.stay_name}</p>
                      <p className="text-xs text-gray-500">{item.stay_id}</p>
                      <p className="text-xs text-gray-500">address_id: {item.address_id}</p>
                    </button>
                  </li>
                );
              })}
            </ul>
          )}
        </div>

        <div className="flex items-center justify-between">
          <p className="text-sm text-gray-600">
            {selectedStay ? `선택됨: ${selectedStay.stay_name}` : '선택된 Stay가 없습니다.'}
          </p>
          <button
            onClick={handleMapSelectedStay}
            disabled={!promotionId || !selectedStay || isMappingStay}
            className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors disabled:opacity-50"
          >
            {isMappingStay ? '추가 중...' : '대상 Stay 추가'}
          </button>
        </div>
      </section>

      <section className="bg-white rounded-lg border border-gray-200 p-4">
        <h2 className="text-lg font-semibold text-gray-900 mb-3">등록된 대상 Stay (현재 세션)</h2>
        {mappedStays.length === 0 ? (
          <p className="text-sm text-gray-500">아직 등록된 대상 Stay가 없습니다.</p>
        ) : (
          <ul className="space-y-2">
            {mappedStays.map((item) => (
              <li
                key={item.id}
                className="px-3 py-2 rounded-md border border-gray-200 flex items-center justify-between"
              >
                <div className="flex flex-col">
                  <span className="text-sm text-gray-800">{item.stayId}</span>
                  <span className="text-xs text-gray-500">{item.id}</span>
                </div>
                <button
                  onClick={() => handleUnmapStay(item.stayId)}
                  disabled={unmappingStayId === item.stayId}
                  className="px-3 py-1.5 text-sm bg-red-50 text-red-700 border border-red-200 rounded-md hover:bg-red-100 transition-colors disabled:opacity-50"
                >
                  {unmappingStayId === item.stayId ? '해제 중...' : '해제'}
                </button>
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
};

export default AdminPromotionPage;
