// 시스템 전역 최소주문금액 하한선(KRW). 저장값이 이 값 미만이면 실제 적용 금액은 하한선으로 올라갑니다.
export const GLOBAL_MIN_ORDER_AMOUNT_FLOOR_KRW = 20000;

/**
 * 가게에 저장된 최소주문금액과 전역 하한선을 비교해 실제 적용되는 최소주문금액을 반환합니다.
 * 저장값이 하한선 미만(0 포함)이면 하한선이 적용되므로 "제한 없음" 상태는 존재하지 않습니다.
 */
export const getEffectiveMinOrderAmountKrw = (storedKrw: number): number => {
  if (!Number.isFinite(storedKrw) || storedKrw < 0) {
    return GLOBAL_MIN_ORDER_AMOUNT_FLOOR_KRW;
  }
  return Math.max(storedKrw, GLOBAL_MIN_ORDER_AMOUNT_FLOOR_KRW);
};

/** 저장값보다 하한선이 더 커서 실제 적용 금액이 올라가는 경우인지 여부. */
export const isMinOrderAmountRaisedByFloor = (storedKrw: number): boolean => {
  return getEffectiveMinOrderAmountKrw(storedKrw) !== storedKrw;
};

/** KRW 정수 금액을 천 단위 구분 표기로 포맷합니다. */
export const formatKrw = (amountKrw: number): string => {
  return `${Math.round(amountKrw).toLocaleString('ko-KR')}원`;
};
