import React, { useState } from 'react';
import { Order } from '../types';
import { completeDelivery, cancelOrder } from '../utils/orderUpdateApi';
import { useToast } from '../hooks/useToast';

interface OrderActionButtonsProps {
  order: Order;
  onUpdate: (orderId: string, updatedOrder: Order) => void;
}

const OrderActionButtons: React.FC<OrderActionButtonsProps> = ({ order, onUpdate }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [isCompletingDelivery, setIsCompletingDelivery] = useState(false);
  const [isCancelling, setIsCancelling] = useState(false);
  const [showCancelModal, setShowCancelModal] = useState(false);
  const { showToast } = useToast();

  // 배달 완료 버튼 표시 조건: PAID, BROKER_ACCEPTED, RESERVATION_PAID, COOKING
  const canCompleteDelivery = order.status === 'PAID' || 
                              order.status === 'BROKER_ACCEPTED' || 
                              order.status === 'RESERVATION_PAID' ||
                              order.status === 'COOKING';

  // 주문 취소 버튼 표시 조건: PAID, BROKER_ACCEPTED, DELIVERY_COMPLETED, COOKING
  const canCancelOrder = order.status === 'PAID' || 
                         order.status === 'BROKER_ACCEPTED' || 
                         order.status === 'DELIVERY_COMPLETED' ||
                         order.status === 'COOKING';

  // 배달 완료 핸들러
  const handleCompleteDelivery = async () => {
    setIsCompletingDelivery(true);
    try {
      const orderResponse = await completeDelivery(order.orderId);
      
      // 성공 시 로컬 상태 업데이트
      const updatedOrder: Order = {
        ...order,
        orderId: orderResponse.id,
        status: orderResponse.status as Order['status']
      };
      
      onUpdate(order.orderId, updatedOrder);
      showToast('배달이 완료되었습니다', 'success');
      
      // 페이지 새로고침
      setTimeout(() => {
        window.location.reload();
      }, 1000);
    } catch (error) {
      showToast(
        error instanceof Error ? error.message : '배달 완료 처리에 실패했습니다. 다시 시도해주세요',
        'error'
      );
    } finally {
      setIsCompletingDelivery(false);
    }
  };

  // 주문 취소 핸들러
  const handleCancelOrder = async () => {
    setShowCancelModal(false);
    setIsCancelling(true);
    try {
      const orderResponse = await cancelOrder(order.orderId);
      
      // 성공 시 로컬 상태 업데이트
      const updatedOrder: Order = {
        ...order,
        orderId: orderResponse.id,
        status: orderResponse.status as Order['status'],
        settlementPrice: 0
      };
      
      onUpdate(order.orderId, updatedOrder);
      showToast('주문이 취소되었습니다', 'success');
      
      // 페이지 새로고침
      setTimeout(() => {
        window.location.reload();
      }, 1000);
    } catch (error) {
      showToast(
        error instanceof Error ? error.message : '주문 취소에 실패했습니다. 다시 시도해주세요',
        'error'
      );
    } finally {
      setIsCancelling(false);
    }
  };

  // 버튼이 하나도 표시되지 않으면 컴포넌트를 렌더링하지 않음
  if (!canCompleteDelivery && !canCancelOrder) {
    return null;
  }

  return (
    <>
      <div className="border-t border-gray-200 pt-4 mt-4">
        {/* 아코디언 헤더 */}
        <button
          onClick={() => setIsExpanded(!isExpanded)}
          className="flex items-center justify-between w-full text-left hover:bg-gray-50 rounded p-2 transition-colors duration-200"
        >
          <h3 className="text-md font-medium text-gray-900">⚡ 주문 액션</h3>
          <svg
            className={`w-5 h-5 text-gray-500 transform transition-transform duration-200 ${
              isExpanded ? 'rotate-180' : ''
            }`}
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
          </svg>
        </button>

        {/* 아코디언 콘텐츠 */}
        {isExpanded && (
          <div className="mt-3 animate-fade-in">
            <div className="flex gap-3">
              {/* 배달 완료 버튼 */}
              {canCompleteDelivery && (
                <button
                  onClick={handleCompleteDelivery}
                  disabled={isCompletingDelivery || isCancelling}
                  className="flex-1 px-4 py-3 bg-green-600 hover:bg-green-700 disabled:bg-gray-400 text-white font-medium rounded-lg transition-colors duration-200 flex items-center justify-center disabled:cursor-not-allowed shadow-sm"
                >
                  {isCompletingDelivery ? (
                    <>
                      <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                      </svg>
                      처리 중...
                    </>
                  ) : (
                    <>
                      <svg className="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                      </svg>
                      배달 완료
                    </>
                  )}
                </button>
              )}

              {/* 주문 취소 버튼 */}
              {canCancelOrder && (
                <button
                  onClick={() => setShowCancelModal(true)}
                  disabled={isCompletingDelivery || isCancelling}
                  className="flex-1 px-4 py-3 bg-red-600 hover:bg-red-700 disabled:bg-gray-400 text-white font-medium rounded-lg transition-colors duration-200 flex items-center justify-center disabled:cursor-not-allowed shadow-sm"
                >
                  <svg className="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                  주문 취소
                </button>
              )}
            </div>
          </div>
        )}
      </div>

      {/* 주문 취소 확인 모달 */}
      {showCancelModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-lg shadow-xl w-full max-w-sm animate-fade-in">
            <div className="p-4 border-b border-gray-200">
              <h3 className="text-lg font-medium text-gray-900">주문 취소 확인</h3>
            </div>
            <div className="p-4">
              <p className="text-gray-700 mb-4">정산금액을 0원으로 설정하시겠습니까? 이 작업은 되돌릴 수 없습니다.</p>
              <div className="flex justify-end gap-2">
                <button
                  onClick={() => setShowCancelModal(false)}
                  disabled={isCancelling}
                  className="px-4 py-2 bg-gray-300 hover:bg-gray-400 text-gray-700 font-medium rounded-md transition-colors duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  취소
                </button>
                <button
                  onClick={handleCancelOrder}
                  disabled={isCancelling}
                  className="px-4 py-2 bg-red-600 hover:bg-red-700 text-white font-medium rounded-md transition-colors duration-200 flex items-center disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {isCancelling ? (
                    <>
                      <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                      </svg>
                      처리 중...
                    </>
                  ) : (
                    '확인'
                  )}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default OrderActionButtons;
