import { useState, useEffect } from 'react';

export const useOrderKey = () => {
  const [key, setKey] = useState<string | null>(null);

  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const keyParam = urlParams.get('key');
    
    if (keyParam) {
      // URL에 키가 있으면 로컬스토리지에 저장
      localStorage.setItem('orderSheetKey', keyParam);
      setKey(keyParam);
    } else {
      // URL에 키가 없으면 로컬스토리지에서 가져오기
      const savedKey = localStorage.getItem('orderSheetKey');
      setKey(savedKey);
    }
  }, []);

  const getSavedKey = () => {
    return localStorage.getItem('orderSheetKey');
  };

  const getNavigationPath = (path: string = '/') => {
    const savedKey = getSavedKey();
    if (savedKey) {
      const separator = path.includes('?') ? '&' : '?';
      return `${path}${separator}key=${savedKey}`;
    }
    return path;
  };

  return {
    key,
    getSavedKey,
    getNavigationPath
  };
};
