import {
  ActivePromotionDetail,
  AddPromotionTargetStayRequest,
  CreatePromotionPolicyRequest,
  CreatePromotionPolicyResponse,
  CreatePromotionRequest,
  CreatePromotionResponse,
  PromotionStaySearchItem,
  PromotionTargetStay,
} from '../types/promotion';
import { ErrorApiResponse } from '../types';

const getApiBaseUrl = () => {
  if (process.env.NODE_ENV === 'development') {
    return process.env.REACT_APP_API_URL || 'http://localhost:8084';
  }

  return process.env.REACT_APP_API_URL || 'https://api.brainbackdoor.com';
};

const API_BASE_URL = getApiBaseUrl();

const getHeaders = () => ({
  'Content-Type': 'application/json',
  Accept: 'application/json',
  'X-SERVER-AUTH': 'secret',
});

const handleResponseError = async (response: Response): Promise<never> => {
  if (response.status === 400) {
    try {
      const errorData = (await response.json()) as ErrorApiResponse;
      throw new Error(errorData.error || errorData.message || '잘못된 요청입니다.');
    } catch (_error) {
      throw new Error('잘못된 요청입니다. 입력값을 확인해주세요.');
    }
  } else if (response.status === 401 || response.status === 403) {
    throw new Error('인증이 필요합니다.');
  } else if (response.status === 404) {
    throw new Error('요청한 리소스를 찾을 수 없습니다.');
  } else if (response.status >= 500) {
    throw new Error('서버에 문제가 발생했습니다. 잠시 후 다시 시도해주세요.');
  }

  throw new Error(`HTTP error! status: ${response.status}`);
};

const handleNetworkError = (error: unknown): never => {
  if (error instanceof TypeError && error.message.includes('fetch')) {
    throw new Error('API 서버에 연결할 수 없습니다. 네트워크 연결을 확인하거나 관리자에게 문의하세요.');
  }

  throw error;
};

const isRecord = (value: unknown): value is Record<string, unknown> => {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
};

const normalizeCreatePromotionResponse = (data: unknown): CreatePromotionResponse => {
  if (isRecord(data) && typeof data.success === 'boolean') {
    return data as unknown as CreatePromotionResponse;
  }

  if (!isRecord(data) || typeof data.id !== 'string') {
    throw new Error('프로모션 생성 응답 형식이 올바르지 않습니다.');
  }

  return {
    success: true,
    data: data as any,
  };
};

const normalizeCreatePolicyResponse = (data: unknown): CreatePromotionPolicyResponse => {
  if (isRecord(data) && typeof data.success === 'boolean') {
    return data as unknown as CreatePromotionPolicyResponse;
  }

  if (!isRecord(data) || typeof data.id !== 'string') {
    throw new Error('정책 추가 응답 형식이 올바르지 않습니다.');
  }

  return {
    success: true,
    data: data as any,
  };
};

export const createPromotion = async (
  payload: CreatePromotionRequest
): Promise<CreatePromotionResponse> => {
  const url = `${API_BASE_URL}/api/v1/promotions`;

  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: getHeaders(),
      mode: 'cors',
      body: JSON.stringify(payload),
    });

    if (!response.ok) {
      await handleResponseError(response);
    }

    const data = await response.json();
    return normalizeCreatePromotionResponse(data);
  } catch (error) {
    handleNetworkError(error);
    throw error;
  }
};

