export const searchStaysByName = async (
  query: string,
  limit = 20
): Promise<PromotionStaySearchItem[]> => {
  const trimmedQuery = query.trim();
  if (trimmedQuery.length < 2) {
    return [];
  }

  const clampedLimit = Math.min(50, Math.max(1, limit));
  const params = new URLSearchParams({
    query: trimmedQuery,
    limit: String(clampedLimit),
  });
  const url = `${API_BASE_URL}/api/stays/search?${params.toString()}`;

  try {
    const response = await fetch(url, {
      method: 'GET',
      headers: getHeaders(),
      mode: 'cors',
    });

    if (!response.ok) {
      await handleResponseError(response);
    }

    const data = (await response.json()) as PromotionStaySearchItem[];
    return Array.isArray(data) ? data : [];
  } catch (error) {
    handleNetworkError(error);
    throw error;
  }
};

