export const addPromotionTargetStay = async (
  promotionId: string,
  payload: AddPromotionTargetStayRequest
): Promise<PromotionTargetStay> => {
  const url = `${API_BASE_URL}/api/v1/promotions/${promotionId}/target-stays`;

  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: getHeaders(),
      mode: 'cors',
      body: JSON.stringify(payload),
    });

    if (!response.ok) {
      await handleResponseError(response);
    }

    return response.json();
  } catch (error) {
    handleNetworkError(error);
    throw error;
  }
};

export const removePromotionTargetStay = async (
  promotionId: string,
  stayId: string
): Promise<void> => {
  const url = `${API_BASE_URL}/api/v1/promotions/${promotionId}/target-stays/${encodeURIComponent(stayId)}`;

  try {
    const response = await fetch(url, {
      method: 'DELETE',
      headers: getHeaders(),
      mode: 'cors',
    });

    if (!response.ok) {
      await handleResponseError(response);
    }
  } catch (error) {
    handleNetworkError(error);
    throw error;
  }
};
