import {
  AdminDeliveryFee,
  AdminLocale,
  AdminLocaleCode,
  AdminMenuPrice,
  AdminMenuTranslation,
  UpdateAdminDeliveryFeeRequest,
  UpdateAdminMenuPriceRequest,
  UpdateAdminMenuTranslationRequest,
} from '../types/menuOperations';

const getApiBaseUrl = () => {
  if (process.env.NODE_ENV === 'development') {
    return process.env.REACT_APP_API_URL || 'http://localhost:8084';
  }
  return process.env.REACT_APP_API_URL || 'https://api.brainbackdoor.com';
};

const getHeaders = () => ({
  'Content-Type': 'application/json',
  Accept: 'application/json',
  'X-SERVER-AUTH': process.env.REACT_APP_SERVER_AUTH || 'secret',
});

const handleResponseError = async (response: Response) => {
  let serverMessage = '';
  try {
    const errorData = await response.json();
    serverMessage = errorData.message || errorData.error || '';
  } catch {
    // Fall through to status-based errors.
  }

  if (serverMessage) {
    throw new Error(serverMessage);
  }

  if (response.status === 400) {
    throw new Error('잘못된 요청입니다. 입력값을 확인해주세요.');
  }
  if (response.status === 403) {
    throw new Error('접근이 거부되었습니다. API 키를 확인해주세요.');
  }
  if (response.status === 404) {
    throw new Error('요청한 리소스를 찾을 수 없습니다.');
  }
  if (response.status >= 500) {
    throw new Error('서버에 문제가 발생했습니다. 잠시 후 다시 시도해주세요.');
  }
  throw new Error(`HTTP error! status: ${response.status}`);
};

const handleNetworkError = (error: unknown) => {
  if (error instanceof TypeError && error.message.includes('fetch')) {
    throw new Error('API 서버에 연결할 수 없습니다. 네트워크 연결을 확인하거나 관리자에게 문의하세요.');
  }
  throw error;
};

const requestJson = async <T>(path: string): Promise<T> => {
  try {
    const response = await fetch(`${getApiBaseUrl()}${path}`, {
      method: 'GET',
      headers: getHeaders(),
      mode: 'cors',
    });

    if (!response.ok) {
      await handleResponseError(response);
    }

    return response.json();
  } catch (error) {
    handleNetworkError(error);
    throw error;
  }
};

const requestNoContent = async (
  path: string,
  method: 'PUT' | 'PATCH',
  body: unknown
): Promise<void> => {
  try {
    const response = await fetch(`${getApiBaseUrl()}${path}`, {
      method,
      headers: getHeaders(),
      mode: 'cors',
      body: JSON.stringify(body),
    });

    if (!response.ok) {
      await handleResponseError(response);
    }
  } catch (error) {
    handleNetworkError(error);
    throw error;
  }
};

export const getAdminLocales = async (): Promise<AdminLocale[]> => {
  return requestJson<AdminLocale[]>('/api/admin/locales');
};

export const getAdminMenuTranslations = async (
  franchiseId: string,
  franchiseMenuId: string
): Promise<AdminMenuTranslation[]> => {
  return requestJson<AdminMenuTranslation[]>(
    `/api/admin/franchises/${franchiseId}/menus/${franchiseMenuId}/translations`
  );
};

export const updateAdminMenuTranslation = async (
  franchiseId: string,
  franchiseMenuId: string,
  languageCode: AdminLocaleCode,
  request: UpdateAdminMenuTranslationRequest
): Promise<void> => {
  return requestNoContent(
    `/api/admin/franchises/${franchiseId}/menus/${franchiseMenuId}/translations/${languageCode}`,
    'PUT',
    request
  );
};

export const getAdminMenuPrice = async (
  franchiseId: string,
  franchiseMenuId: string
): Promise<AdminMenuPrice> => {
  return requestJson<AdminMenuPrice>(
    `/api/admin/franchises/${franchiseId}/menus/${franchiseMenuId}/price`
  );
};

export const updateAdminMenuPrice = async (
  franchiseId: string,
  franchiseMenuId: string,
  request: UpdateAdminMenuPriceRequest
): Promise<void> => {
  return requestNoContent(
    `/api/admin/franchises/${franchiseId}/menus/${franchiseMenuId}/price`,
    'PATCH',
    request
  );
};

export const getAdminDeliveryFees = async (): Promise<AdminDeliveryFee[]> => {
  const result = await requestJson<AdminDeliveryFee[]>('/api/admin/delivery-fees');
  return [...result].sort((a, b) => a.displayOrder - b.displayOrder);
};

export const updateAdminDeliveryFee = async (
  policyKey: string,
  request: UpdateAdminDeliveryFeeRequest
): Promise<void> => {
  return requestNoContent(`/api/admin/delivery-fees/${policyKey}`, 'PATCH', request);
};
