import React from 'react';

export type OrderType = 'food' | 'gift' | 'reservation';

interface OrderTypeTabProps {
  activeTab: OrderType;
  onTabChange: (tab: OrderType) => void;
}

const OrderTypeTab: React.FC<OrderTypeTabProps> = ({ activeTab, onTabChange }) => {
  return (
    <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-4 mb-4">
      <div className="flex bg-gray-100 rounded-lg p-1">
        <button
          onClick={() => onTabChange('food')}
          className={`flex-1 px-4 py-2 rounded-md text-sm font-medium transition-colors ${
            activeTab === 'food'
              ? 'bg-blue-600 text-white shadow-sm'
              : 'text-gray-600 hover:text-gray-900'
          }`}
        >
          🍕 바로배달
        </button>
        <button
          onClick={() => onTabChange('reservation')}
          className={`flex-1 px-4 py-2 rounded-md text-sm font-medium transition-colors ${
            activeTab === 'reservation'
              ? 'bg-blue-600 text-white shadow-sm'
              : 'text-gray-600 hover:text-gray-900'
          }`}
        >
          ⏰ 예약배달
        </button>
        {/* 기프트샵 탭은 숨김 처리 */}
      </div>
    </div>
  );
};

export default OrderTypeTab; 