import { AdminLocaleCode } from '../types/menuOperations';
import {
  AdminFranchiseDetail,
  AdminFranchiseImageUploadResponse,
  AdminFranchiseTranslation,
  UpdateAdminFranchiseTranslationRequest,
} from '../types/franchiseAdmin';

const getApiBaseUrl = () => {
  if (process.env.NODE_ENV === 'development') {
    return process.env.REACT_APP_API_URL || 'http://localhost:8084';
  }
  return process.env.REACT_APP_API_URL || 'https://api.brainbackdoor.com';
};

const getServerAuth = () => process.env.REACT_APP_SERVER_AUTH || 'secret';

const getJsonHeaders = () => ({
  'Content-Type': 'application/json',
  Accept: 'application/json',
  'X-SERVER-AUTH': getServerAuth(),
});

const handleResponseError = async (response: Response) => {
  let serverMessage = '';
  try {
    const errorData = await response.json();
    serverMessage = errorData.message || errorData.error || '';
  } catch {
    // Fall through to status-based errors.
  }

  if (serverMessage) {
    throw new Error(serverMessage);
  }

  if (response.status === 400) {
    throw new Error('잘못된 요청입니다. 입력값을 확인해주세요.');
  }
  if (response.status === 403) {
    throw new Error('접근이 거부되었습니다. API 키를 확인해주세요.');
  }
  if (response.status === 404) {
    throw new Error('요청한 리소스를 찾을 수 없습니다.');
  }
  if (response.status >= 500) {
    throw new Error('서버에 문제가 발생했습니다. 잠시 후 다시 시도해주세요.');
  }
  throw new Error(`HTTP error! status: ${response.status}`);
};

const handleNetworkError = (error: unknown) => {
  if (error instanceof TypeError && error.message.includes('fetch')) {
    throw new Error('API 서버에 연결할 수 없습니다. 네트워크 연결을 확인하거나 관리자에게 문의하세요.');
  }
  throw error;
};

const requestJson = async <T>(path: string): Promise<T> => {
  try {
    const response = await fetch(`${getApiBaseUrl()}${path}`, {
      method: 'GET',
      headers: getJsonHeaders(),
      mode: 'cors',
    });

    if (!response.ok) {
      await handleResponseError(response);
    }

    return response.json();
  } catch (error) {
    handleNetworkError(error);
    throw error;
  }
};

const requestMutation = async (
  path: string,
  method: 'PUT' | 'PATCH' | 'DELETE',
  body?: unknown
): Promise<void> => {
  try {
    const response = await fetch(`${getApiBaseUrl()}${path}`, {
      method,
      headers: getJsonHeaders(),
      mode: 'cors',
      ...(body === undefined ? {} : { body: JSON.stringify(body) }),
    });

    if (!response.ok) {
      await handleResponseError(response);
    }
  } catch (error) {
    handleNetworkError(error);
    throw error;
  }
};

export const getAdminFranchiseDetail = async (
  franchiseId: string
): Promise<AdminFranchiseDetail> => {
  return requestJson<AdminFranchiseDetail>(`/api/admin/franchises/${franchiseId}`);
};

export const getAdminFranchiseTranslations = async (
  franchiseId: string
): Promise<AdminFranchiseTranslation[]> => {
  return requestJson<AdminFranchiseTranslation[]>(
    `/api/admin/franchises/${franchiseId}/translations`
  );
};

export const updateAdminFranchiseTranslation = async (
  franchiseId: string,
  languageCode: AdminLocaleCode,
  request: UpdateAdminFranchiseTranslationRequest
): Promise<void> => {
  return requestMutation(
    `/api/admin/franchises/${franchiseId}/translations/${languageCode}`,
    'PUT',
    request
  );
};

export const uploadAdminFranchiseImage = async (
  franchiseId: string,
  file: File
): Promise<AdminFranchiseImageUploadResponse> => {
  const formData = new FormData();
  formData.append('file', file);

  try {
    const response = await fetch(`${getApiBaseUrl()}/api/admin/franchises/${franchiseId}/image`, {
      method: 'POST',
      headers: {
        Accept: 'application/json',
        'X-SERVER-AUTH': getServerAuth(),
      },
      mode: 'cors',
      body: formData,
    });

    if (!response.ok) {
      await handleResponseError(response);
    }

    return response.json();
  } catch (error) {
    handleNetworkError(error);
    throw error;
  }
};

export const deleteAdminFranchiseImage = async (franchiseId: string): Promise<void> => {
  return requestMutation(`/api/admin/franchises/${franchiseId}/image`, 'DELETE');
};
