import React, { useEffect, useRef } from 'react';

interface NaverMapComponentProps {
  address: string;
  lat: number;
  lng: number;
}

const NaverMapComponent: React.FC<NaverMapComponentProps> = ({ address, lat, lng }) => {
  const mapRef = useRef<HTMLDivElement>(null);
  const [isMapLoaded, setIsMapLoaded] = React.useState(false);
  const [isLoading, setIsLoading] = React.useState(true);

  useEffect(() => {
    let retryCount = 0;
    const maxRetries = 50; // 5초 동안 재시도
    
    const initMap = () => {
      try {
        if (mapRef.current && (window as any).naver && (window as any).naver.maps) {
          console.log('네이버 지도 초기화 시작:', { lat, lng, address });
          const naver = (window as any).naver;
          const center = new naver.maps.LatLng(lat, lng);
          
          const map = new naver.maps.Map(mapRef.current, {
            center: center,
            zoom: 17,
          });

          new naver.maps.Marker({
            position: center,
            map: map,
            title: address,
          });
          
          console.log('네이버 지도 로딩 완료');
          setIsMapLoaded(true);
          setIsLoading(false);
        }
      } catch (error) {
        console.error('네이버 지도 초기화 실패:', error);
        setIsLoading(false);
      }
    };

    const checkNaver = () => {
      retryCount++;
      console.log(`네이버 지도 로딩 시도 ${retryCount}/${maxRetries}`, {
        naverExists: !!(window as any).naver,
        naverMapsExists: !!(window as any).naver?.maps,
        naverObject: (window as any).naver,
        windowKeys: Object.keys(window).filter(key => key.includes('naver') || key.includes('Naver'))
      });
      
      if ((window as any).naver && (window as any).naver.maps) {
        initMap();
      } else if (retryCount < maxRetries) {
        setTimeout(checkNaver, 100);
      } else {
        console.error('네이버 지도 로딩 시간 초과');
        setIsLoading(false);
      }
    };

    // 네이버 지도 로딩 이벤트 리스너
    const handleNaverMapsLoaded = () => {
      console.log('네이버 지도 로딩 이벤트 수신');
      initMap();
    };

    window.addEventListener('naver-maps-loaded', handleNaverMapsLoaded);
    
    // 즉시 확인도 수행
    if ((window as any).naver && (window as any).naver.maps) {
      initMap();
    } else {
      checkNaver();
    }

    return () => {
      window.removeEventListener('naver-maps-loaded', handleNaverMapsLoaded);
    };
  }, [address, lat, lng]);

  return (
    <div className="w-full">
      <div className="mb-3">
        <h3 className="text-lg font-semibold text-gray-900 mb-2">🗺️ Naver 지도 (한글 주소)</h3>
        <p className="text-sm text-gray-600">{address}</p>
      </div>
      <div 
        ref={mapRef} 
        className="w-full h-64 bg-gray-200 rounded-lg border border-gray-300 relative"
        style={{ minHeight: '256px' }}
      >
        {isLoading && (
          <div className="absolute inset-0 flex items-center justify-center bg-gray-100 rounded-lg">
            <div className="text-center">
              <svg className="animate-spin h-8 w-8 text-blue-500 mx-auto mb-2" fill="none" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
              </svg>
              <p className="text-sm text-gray-600">네이버 지도 로딩 중...</p>
            </div>
          </div>
        )}
        {!isLoading && !isMapLoaded && (
          <div className="absolute inset-0 flex items-center justify-center bg-red-50 rounded-lg">
            <div className="text-center">
              <svg className="h-8 w-8 text-red-500 mx-auto mb-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.732-.833-2.464 0L3.34 16.5c-.77.833.192 2.5 1.732 2.5z" />
              </svg>
              <p className="text-sm text-red-600">네이버 지도를 로딩할 수 없습니다</p>
              <p className="text-xs text-red-500 mt-1">개발자 도구의 콘솔을 확인해주세요</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default NaverMapComponent;
