import React from 'react';
import { DateFilter } from '../types';

interface FilterToggleProps {
  dateFilter: DateFilter;
  onToggle: (dateFilter: DateFilter) => void;
  todayCount: number | null;
  yesterdayCount: number | null;
  totalCount: number | null;
}

const FilterToggle: React.FC<FilterToggleProps> = ({ 
  dateFilter, 
  onToggle, 
  todayCount, 
  yesterdayCount,
  totalCount 
}) => {
  const getFilterLabel = () => {
    switch (dateFilter) {
      case DateFilter.TODAY:
        return todayCount !== null ? `오늘 주문 ${todayCount}건 표시 중` : '오늘 주문 표시 중';
      case DateFilter.YESTERDAY:
        return yesterdayCount !== null ? `어제 주문 ${yesterdayCount}건 표시 중` : '어제 주문 표시 중';
      case DateFilter.ALL:
        return totalCount !== null ? `전체 주문 ${totalCount}건 표시 중` : '전체 주문 표시 중';
    }
  };

  return (
    <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-4 mb-4">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-md font-medium text-gray-900">주문 필터</h3>
          <p className="text-sm text-gray-600">
            {getFilterLabel()}
          </p>
        </div>
        
        <div className="flex bg-gray-100 rounded-lg p-1">
          <button
            onClick={() => onToggle(DateFilter.TODAY)}
            className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${
              dateFilter === DateFilter.TODAY
                ? 'bg-blue-600 text-white shadow-sm'
                : 'text-gray-600 hover:text-gray-900'
            }`}
          >
            오늘 주문
            {todayCount !== null && <span className="ml-1 text-xs">({todayCount})</span>}
          </button>
          <button
            onClick={() => onToggle(DateFilter.YESTERDAY)}
            className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${
              dateFilter === DateFilter.YESTERDAY
                ? 'bg-blue-600 text-white shadow-sm'
                : 'text-gray-600 hover:text-gray-900'
            }`}
          >
            어제 주문
            {yesterdayCount !== null && <span className="ml-1 text-xs">({yesterdayCount})</span>}
          </button>
          <button
            onClick={() => onToggle(DateFilter.ALL)}
            className={`px-4 py-2 rounded-md text-sm font-medium transition-colors ${
              dateFilter === DateFilter.ALL
                ? 'bg-blue-600 text-white shadow-sm'
                : 'text-gray-600 hover:text-gray-900'
            }`}
          >
            전체 주문
            {totalCount !== null && <span className="ml-1 text-xs">({totalCount})</span>}
          </button>
        </div>
      </div>
    </div>
  );
};

export default FilterToggle; 