// 카테고리 생성
export const createManualCategory = async (
  data: CreateManualCategoryRequest
): Promise<ManualCategoryCreateApiResponse> => {
  const url = `${API_BASE_URL}/api/manual-categories`;
  
  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: getHeaders(true), // 생성은 인증 필요
      mode: 'cors',
      body: JSON.stringify(data),
    });

    if (!response.ok) {
      await handleResponseError(response);
    }

    return response.json();
  } catch (error) {
    handleNetworkError(error);
    throw error;
  }
};

