import React from 'react';
import { HostListItem } from '../types';
import { formatDate } from '../utils/dateUtils';

interface HostCardProps {
  hostItem: HostListItem;
  onClick: () => void;
}

const HostCard: React.FC<HostCardProps> = ({ hostItem, onClick }) => {
  const { host, stays } = hostItem;
  const hasBankbook = host.bankbookUrl !== null && host.bankbookUrl !== undefined;
  const hasBusinessRegistration = host.businessRegistrationUrl !== null && host.businessRegistrationUrl !== undefined;
  const stayCount = stays.length;

  return (
    <div
      onClick={onClick}
      className="bg-white rounded-lg shadow-md p-6 cursor-pointer hover:shadow-lg transition-all duration-200 transform hover:scale-105"
    >
      {/* 호스트명 */}
      <h3 className="text-xl font-semibold text-gray-900 mb-3">{host.hostName}</h3>

      {/* 연락처 */}
      <p className="text-gray-600 mb-4">{host.contact}</p>

      {/* 배지 영역 */}
      <div className="flex flex-wrap gap-2 mb-4">
        {/* 통장사본 유무 배지 */}
        <span
          className={`px-3 py-1 rounded-full text-sm font-medium ${
            hasBankbook
              ? 'bg-green-100 text-green-800'
              : 'bg-gray-100 text-gray-600'
          }`}
        >
          {hasBankbook ? '✓ 통장사본' : '통장사본 없음'}
        </span>

        {/* 사업자등록증 유무 배지 */}
        <span
          className={`px-3 py-1 rounded-full text-sm font-medium ${
            hasBusinessRegistration
              ? 'bg-green-100 text-green-800'
              : 'bg-gray-100 text-gray-600'
          }`}
        >
          {hasBusinessRegistration ? '✓ 사업자등록증' : '사업자등록증 없음'}
        </span>

        {/* Stay 개수 배지 */}
        <span className="px-3 py-1 rounded-full text-sm font-medium bg-blue-100 text-blue-800">
          Stay {stayCount}개
        </span>
      </div>

      {/* 날짜 정보 */}
      <div className="text-sm text-gray-500">
        <p>생성일: {formatDate(host.createdDate)}</p>
        {host.updatedDate !== host.createdDate && (
          <p>수정일: {formatDate(host.updatedDate)}</p>
        )}
      </div>
    </div>
  );
};

export default HostCard;

