import {
  AdminStoreDetail,
  AdminStoreMenu,
  AdminStoreSummary,
  PatchAdminFranchiseStoreOperatingHoursRequest,
  SetAdminStoreSuspensionRequest,
  UpdateAdminFranchiseMenuAvailabilityRequest,
  UpdateAdminFranchiseStoreMinimumOrderAmountRequest,
  UpdateAdminFranchiseStoreOperatingHoursRequest,
  UpdateAdminOperatingHoursRequest,
  UpdateAdminStoreMenuAvailabilityRequest,
  UpdateAdminStoreMinimumOrderAmountRequest,
} from '../types/storeLiveOps';

const getApiBaseUrl = () => {
  if (process.env.NODE_ENV === 'development') {
    return process.env.REACT_APP_API_URL || 'http://localhost:8084';
  }
  return process.env.REACT_APP_API_URL || 'https://api.brainbackdoor.com';
};

const getHeaders = () => ({
  'Content-Type': 'application/json',
  Accept: 'application/json',
  'X-SERVER-AUTH': process.env.REACT_APP_SERVER_AUTH || 'secret',
});

const handleResponseError = async (response: Response) => {
  let serverMessage = '';
  try {
    const errorData = await response.json();
    serverMessage = errorData.message || errorData.error || '';
  } catch {
    // Ignore malformed error bodies and fall back to status messages.
  }

  if (serverMessage) {
    throw new Error(serverMessage);
  }

  if (response.status === 400) {
    throw new Error('잘못된 요청입니다. 입력값을 확인해주세요.');
  }
  if (response.status === 403) {
    throw new Error('접근이 거부되었습니다. API 키를 확인해주세요.');
  }
  if (response.status === 404) {
    throw new Error('요청한 리소스를 찾을 수 없습니다.');
  }
  if (response.status >= 500) {
    throw new Error('서버에 문제가 발생했습니다. 잠시 후 다시 시도해주세요.');
  }
  throw new Error(`HTTP error! status: ${response.status}`);
};

const handleNetworkError = (error: unknown) => {
  if (error instanceof TypeError && error.message.includes('fetch')) {
    throw new Error('API 서버에 연결할 수 없습니다. 네트워크 연결을 확인하거나 관리자에게 문의하세요.');
  }
  throw error;
};

const requestJson = async <T>(path: string): Promise<T> => {
  try {
    const response = await fetch(`${getApiBaseUrl()}${path}`, {
      method: 'GET',
      headers: getHeaders(),
      mode: 'cors',
    });

    if (!response.ok) {
      await handleResponseError(response);
    }

    return response.json();
  } catch (error) {
    handleNetworkError(error);
    throw error;
  }
};

const requestNoContent = async (
  path: string,
  method: 'PUT' | 'POST' | 'DELETE' | 'PATCH',
  body?: unknown
): Promise<void> => {
  try {
    const response = await fetch(`${getApiBaseUrl()}${path}`, {
      method,
      headers: getHeaders(),
      mode: 'cors',
      ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
    });

    if (!response.ok) {
      await handleResponseError(response);
    }
  } catch (error) {
    handleNetworkError(error);
    throw error;
  }
};

export const getAdminStoresByFranchise = async (
  franchiseId: string
): Promise<AdminStoreSummary[]> => {
  return requestJson<AdminStoreSummary[]>(`/api/admin/franchises/${franchiseId}/stores`);
};

export const getAdminStoreDetail = async (storeId: string): Promise<AdminStoreDetail> => {
  return requestJson<AdminStoreDetail>(`/api/admin/stores/${storeId}`);
};

export const getAdminStoreMenus = async (storeId: string): Promise<AdminStoreMenu[]> => {
  return requestJson<AdminStoreMenu[]>(`/api/admin/stores/${storeId}/menus`);
};

export const updateAdminStoreOperatingHours = async (
  storeId: string,
  request: UpdateAdminOperatingHoursRequest
): Promise<void> => {
  return requestNoContent(`/api/admin/stores/${storeId}/operating-hours`, 'PUT', request);
};

export const setAdminStoreSuspension = async (
  storeId: string,
  request: SetAdminStoreSuspensionRequest
): Promise<void> => {
  return requestNoContent(`/api/admin/stores/${storeId}/suspension`, 'POST', request);
};

export const clearAdminStoreSuspension = async (storeId: string): Promise<void> => {
  return requestNoContent(`/api/admin/stores/${storeId}/suspension`, 'DELETE');
};

export const updateAdminStoreMenuAvailability = async (
  storeId: string,
  storeMenuId: string,
  available: boolean
): Promise<void> => {
  const request: UpdateAdminStoreMenuAvailabilityRequest = { available };
  return requestNoContent(
    `/api/admin/stores/${storeId}/menus/${storeMenuId}/availability`,
    'PATCH',
    request
  );
};

